                        i = cmd.ExecuteNonQuery();
                        cmd.Dispose();
                        con.Close();

                        if (i > 0)
                        {
                            comman.Code = 201;
                            comman.Message = "Record has been updated successfully.";
                        }
                        else
                        {
                            comman.Code = 410;
                            comman.Message = "Problem has been occurred while submitting your data.";
                        }
                    }


                }
                catch (SqlException ex)
                {
                    if (ex.Number == 2601 || ex.Number == 2627)
                    {
                        comman.Code = 405;
                        comman.Message = "Cannot insert duplicate values..";
                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                    }

                }


                JavaScriptSerializer js = new JavaScriptSerializer();
                js.MaxJsonLength = Int32.MaxValue;
                Context.Response.Write(js.Serialize(comman));
            }
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void DeleteCompanyMaster()
        {
            JavaScriptSerializer js;
            List<CompanyMaster> listUser = new List<CompanyMaster>();
            CompanyMasterResponse response = new CompanyMasterResponse();

            CompanyMaster ilist = new CompanyMaster();

            CommanResponse comman = new CommanResponse();

            ilist.CompanyId = Convert.ToInt32(HttpContext.Current.Request.Params["CompanyIds"]);

            //get data
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select * " +
                    " from CompanyMaster where CompanyId = " + ilist.CompanyId + "";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    string photo = "";
                    string sign = "";

                    while (rdr.Read())
                    {
                        photo = rdr["CompanyLogo"].ToString();
                        sign = rdr["Sign"].ToString();
                    }


                    string path = Server.MapPath(@"" + photo);
                    FileInfo filess = new FileInfo(path);
                    if (filess.Exists)
                    {
                        filess.Delete();
                    }

                    string path1 = Server.MapPath(@"" + sign);
                    FileInfo filess1 = new FileInfo(path1);
                    if (filess1.Exists)
                    {
                        filess1.Delete();
                    }

                    rdr.Close();
                    cmd.Dispose();
                    con.Close();

                    try
                    {
                        cmd.Connection = con;
                        cmd.CommandText = "DELETE FROM CompanyMaster WHERE CompanyId = " + ilist.CompanyId + " ";
                        con.Open();
                        int i = cmd.ExecuteNonQuery();
                        con.Close();
                        if (i > 0)
                        {
                            comman.Code = 200;
                            comman.Message = "Record Deleted Successfully.";
                            js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }

                        else
                        {
                            comman.Code = 410;
                            comman.Message = "Failed to delete record.";
                            js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;
                        }
                    }
                    catch (SqlException ex)
                    {
                        con.Close();
                        comman.Code = 405;
                        comman.Message = "Problem has been occurred while deleting your data";
                        js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;

                    }

                }
                else
                {
                    con.Close();
                    comman.Code = 404;
                    comman.Message = "Record not found.";
                    js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
                    Context.Response.Write(js.Serialize(comman));
                    return;
                }


            }

        }

