        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getGstSlab(string startFrom)
        {
            JavaScriptSerializer js;
            List<GstSlabMaster> listUser = new List<GstSlabMaster>();
            GstSlabMasterResponse response = new GstSlabMasterResponse();

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select GS.*, CM.CompanyName from GSTSLABMaster GS LEFT JOIN CompanyMaster CM ON GS.CompanyId = CM.CompanyId order by GS.GSTSLABId desc OFFSET " + startFrom.ToString() + " ROWS FETCH NEXT 10 ROWS ONLY";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {

                        GstSlabMaster condition = new GstSlabMaster();
                        condition.GSTSLABId = Convert.ToInt32(rdr["GSTSLABId"].ToString());
                        condition.dates = Convert.ToDateTime(rdr["date"].ToString()).ToString("dd-MM-yyyy");
                        condition.CompanyName = rdr["CompanyName"].ToString();
                        condition.GSTSLABName = rdr["GSTSLABName"].ToString();
                        condition.GST = Convert.ToDecimal(rdr["GST"].ToString());
                        condition.IGST = Convert.ToDecimal(rdr["IGST"].ToString());
                        condition.CESS = Convert.ToDecimal(rdr["CESS"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 200;
            response.Message = "Success";
            response.listGstSlabMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;

        }

