        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getDesignSpecificationMaster()
        {

            JavaScriptSerializer js;
            List<DesignSpecificationMaster> listUser = new List<DesignSpecificationMaster>();
            DesignSpecificationMasterResponse response = new DesignSpecificationMasterResponse();

            var request = HttpContext.Current.Request;
            DesignSpecificationMaster ilist = new DesignSpecificationMaster();

            ilist.searchDesignSpecification = HttpContext.Current.Request.Params["searchDesignSpecification"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];



            if (ilist.searchDesignSpecification != "")
            {
                ilist.searchDesignSpecification = " where  " +
                    " DesignSpecification LIKE '%" + ilist.searchDesignSpecification + "%' ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = "select * " +
                    "from DesignSpecificationMaster " + ilist.searchDesignSpecification + "" +
                    "order by Position desc" +
                " OFFSET " + ilist.startFrom + " ROWS FETCH NEXT 10 ROWS ONLY ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        DesignSpecificationMaster condition = new DesignSpecificationMaster();
                        condition.DesignSpecificationID = Convert.ToInt32(rdr["DesignSpecificationID"].ToString());
                        condition.IsActive = Convert.ToInt32(rdr["IsActive"].ToString());
                        condition.Position = Convert.ToInt32(rdr["Position"].ToString());
                        condition.DateandTime = Convert.ToDateTime(rdr["DateandTime"].ToString());
                        condition.DateandTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                        condition.DesignSpecification = rdr["DesignSpecification"].ToString().ToUpper();
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listDesignSpecificationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;

        }
