        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void EditDesignCategoryMaster()
        {
            DateTime dateTime_Indian = TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, India_Standard_Time);

            var request = HttpContext.Current.Request;

            CommanResponse comman = new CommanResponse();
            DesignCategoryMaster ilist = new DesignCategoryMaster();
            ilist.DesignCategoryID = Convert.ToInt32(HttpContext.Current.Request.Params["DesignCategoryID"]);
            ilist.DesignCategory = HttpContext.Current.Request.Params["DesignCategory"];
            ilist.IsActive = Convert.ToInt32(HttpContext.Current.Request.Params["IsActive"]);
            ilist.UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
            ilist.CompanyId = Convert.ToInt32(Context.Request.Cookies["CompanyID"].Value.Split('=')[1]);


            try
            {


                if (ilist.DesignCategory == "")
                {
                    comman.Code = 410;
                    comman.Message = "Please Mention Warp Quality.";
                }
                else
                {
                    int i = 0;
                    string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                    using (SqlConnection con = new SqlConnection(cs))
                    {
                        SqlCommand cmd;
                        cmd = new SqlCommand();
                        cmd.Connection = con;
                        cmd.CommandType = System.Data.CommandType.Text;
                        cmd.CommandType = System.Data.CommandType.Text;
                        string sql = String.Format("Update DesignCategoryMaster set DesignCategory = @DesignCategory, IsActive = '" + ilist.IsActive + "', UserAccountId = '" + ilist.UserAccountId + "', CompanyId = '" + ilist.CompanyId + "' where " +
                                    " DesignCategoryID = '" + ilist.DesignCategoryID + "' ");

                        cmd.CommandText = sql;
                        cmd.Parameters.Add("@DesignCategory", SqlDbType.NVarChar).Value = ilist.DesignCategory.ToUpper();

                        con.Open();
                        i = cmd.ExecuteNonQuery();
                        cmd.Dispose();
                        con.Close();

                        if (i > 0)
                        {
                            comman.Code = 201;
                            comman.Message = "Warp Quality has been updated successfully.";
                        }
                        else
                        {
                            comman.Code = 410;
                            comman.Message = "Warp Quality is already Exists.";
                        }

                    }
                }



            }
            catch (SqlException ex)
            {
                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";

                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                }

            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
