            //ilist.DesignEntryFormID = Convert.ToInt32(HttpContext.Current.Request.Params["DesignEntryFormID"]);
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = HttpContext.Current.Request.Params["DesignEntryFormID"].Replace("==", "") + "%3d%3d";
                ilist.DesignEntryFormID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                ilist.DesignEntryFormID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["DesignEntryFormID"])));
            }

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = " select DEFM.*, WQM.WarpQuality, DM.DesignerName, SM.Sketcher, TM.Type, DCM.DesignCategory " +
