                        DEntryForm.DesignNo = rdr["DesignNo"].ToString().ToUpper();
                        DEntryForm.Remark = rdr["Remark"].ToString().ToUpper();
                        DEntryForm.PickOnLoom = Convert.ToInt32(rdr["PickOnLoom"].ToString());
                        DEntryForm.TotalCard = Convert.ToDecimal(rdr["TotalCard"].ToString());
                        DEntryForm.AveragePic = Convert.ToDecimal(rdr["AveragePic"].ToString());
                        DEntryForm.ReedOnLoom = rdr["ReedOnLoom"].ToString().ToUpper();
                        DEntryForm.TypeID = Convert.ToInt32(rdr["TypeID"].ToString());
                        DEntryForm.Type = rdr["Type"].ToString().ToUpper();
                        DEntryForm.DesignCategoryID = Convert.ToInt32(rdr["DesignCategoryID"].ToString());
                        DEntryForm.DesignCategory = rdr["DesignCategory"].ToString().ToUpper();
                        DEntryForm.SketcherID = Convert.ToInt32(rdr["SketcherID"].ToString());
                        DEntryForm.Sketcher = rdr["Sketcher"].ToString().ToUpper();
                        DEntryForm.DesignCut = rdr["DesignCut"].ToString().ToUpper();
                        DEntryForm.SaleRate = Convert.ToDecimal(rdr["SaleRate"]);
                        DEntryForm.BarcodeNo = rdr["BarcodeNo"].ToString().ToUpper();


                        //Purchase invoice Items Details
                        SqlCommand cmd1 = new SqlCommand();
                        cmd1.Connection = con;
                        cmd1.CommandType = System.Data.CommandType.Text;
                        cmd1.CommandText = "select DEWD.*, YMM.YarnMaterial, DSM.DesignSpecification from DesignEntryWeftData DEWD " +
                            " LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = DEWD.YarnMaterialID " +
                            " LEFT JOIN DesignSpecificationMaster DSM ON DSM.DesignSpecificationID = DEWD.DesignSpecificationID" +
                            " where DEWD.DesignEntryFormID = " + ilist.DesignEntryFormID + " ";
                        //con.Open();
                        SqlDataReader rdr1 = cmd1.ExecuteReader();

                        //con.Close();
                        if (rdr1.HasRows)
                        {
                            List<DesignEntryWeftData> DesignEntryWeftDetails = new List<DesignEntryWeftData>();
                            while (rdr1.Read())
                            {
