                                WarpData.YarnQualityMaterialID = Convert.ToInt32(rdr2["YarnQualityMaterialID"]);
                                WarpData.Tar = Convert.ToInt32(rdr2["Tar"]);
                                WarpData.YarnMaterial = rdr2["YarnMaterial"].ToString().ToUpper();
                                allDesignFormWarpMaster.Add(WarpData);
                            }
                            DEntryForm.listDesignFormWarpData = allDesignFormWarpMaster;
                        }
                        rdr2.Close();
                        cmd2.Dispose();

                        listDesignEntryForm.Add(DEntryForm);

                    }

                    ilistDesignEntryForm.Code = 200;
                    ilistDesignEntryForm.Message = "Success";
                    ilistDesignEntryForm.listDesignEntryForm = listDesignEntryForm;
                }
                else
                {
                    ilistDesignEntryForm.Code = 105;
                    ilistDesignEntryForm.Message = "Opps! Purchase Order Not Exist.";
                    ilistDesignEntryForm.listDesignEntryForm = listDesignEntryForm;
                }
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(ilistDesignEntryForm));
            return;


        }
