                                           " ( '" + id + "' , '" + each.MatchingNo + "', '" + MatchingID + "' , " +
                                           "  '" + each.WarpMatchingID + "', '" + each.Warp1 + "', '" + each.Warp2 + "' , '" + each.Warp3 + "', '" + each.Warp4 + "', '" + each.Warp5 + "' , '" + each.Warp6 + "' , '" + each.Warp7 + "' , '" + each.Warp8 + "' , '" + each.Warp9 + "' , '" + each.Warp10 + "' , " +
                                           " '" + each.FeederMatchingID + "', '" + each.Feeder1 + "' , '" + each.Feeder2 + "', '" + each.Feeder3 + "', '" + each.Feeder4 + "' , '" + each.Feeder5 + "', '" + each.Feeder6 + "', '" + each.Feeder7 + "', '" + each.Feeder8 + "', '" + each.Feeder9 + "', '" + each.Feeder10 + "', " +
                                           " '" + each.Feeder11 + "' , '" + each.Feeder12 + "', '" + each.Feeder13 + "', '" + each.Feeder14 + "' , '" + each.Feeder15 + "', '" + each.Feeder16 + "', '" + each.Feeder17 + "', '" + each.Feeder18 + "', '" + each.Feeder19 + "', '" + each.Feeder20 + "',  " +
                                           " '" + each.Feeder21 + "' , '" + each.Feeder22 + "', '" + each.Feeder23 + "', '" + each.Feeder24 + "' , '" + each.Feeder25 + "', '" + each.Feeder26 + "', '" + each.Feeder27 + "', '" + each.Feeder28 + "', '" + each.Feeder29 + "', '" + each.Feeder30 + "',0,0 )");

                                    cmd.CommandText = sqls;
                                    cmd.ExecuteNonQuery();

                                }
                            }



                            con.Close();

                            comman.id = Convert.ToInt32(id);
                            comman.Code = 200;
                            comman.Message = "Record has been saved successfully";

                        }
                        else
                        {

                            comman.Code = 500;
                            comman.Message = "Problem has been occurred while submitting your data.";

                        }
                        cmd.Dispose();
                        con.Close();

                    }
