            try
            {

                int i = 0;
                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;



                    cmd.Connection = con;
                    cmd.CommandType = System.Data.CommandType.Text;
                    con.Open();

                    // Check GSTIN
                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE GSTIN = @GSTIN";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@GSTIN", ilist.GSTIN);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This GSTIN {ilist.GSTIN} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if GSTIN exists
                        }
                    }

                    // Check PAN
                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE PAN = @PAN";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@PAN", ilist.PanNo);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This PAN no {ilist.PanNo} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if PAN exists
                        }
                    }

                    // Check MobileNo
                    cmd.CommandText = "SELECT 1 FROM PartyMaster WHERE MobileNo = @MobileNo";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@MobileNo", ilist.MobileNo);
                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        if (rdr.Read())
                        {
                            comman.Code = 410;
                            comman.Message = $"This Mobile No {ilist.MobileNo} already exists.";
                            JavaScriptSerializer js = new JavaScriptSerializer();
                            js.MaxJsonLength = Int32.MaxValue;
                            Context.Response.Write(js.Serialize(comman));
                            return;  // stop here if Mobile exists
                        }
                    }




                    cmd.CommandType = System.Data.CommandType.Text;

                    string sql = String.Format("Insert Into PartyMaster (CompanyId, UserAccountId, DateAndTime, PartyName, MobileNo, AlterMobileNo, Email, BillingAddress, ShippingAddress, IsSameAddress, GSTIN, PAN, State, City, Pincode, BankHolderName, BankAccountNo, BankIFSCCode, BankName, BankBranch, IsActiveParty) OUTPUT INSERTED.PartyId Values " +
                                    " ((select CompanyId from companymaster where is_default = 1), '" + ilist.UserAccountId + "', '" + dateTime_Indian.ToString("yyyy-MM-dd HH:mm:ss") + "', @PartyName , '" + ilist.MobileNo + "', '" + ilist.AlterMobileNo + "', '" + ilist.Email + "', @BillingAddress, @ShippingAddress, '" + ilist.IsSameAddress + "', '" + ilist.GSTIN + "', '" + ilist.PanNo + "', '" + ilist.State + "', '" + ilist.City + "', '" + ilist.Pincode + "',   " +
                                    "   @BankHolderName, '" + ilist.BankAccountNo + "', '" + ilist.BankIFSCCode + "', @BankName, @BankBranch, '" + ilist.IsActiveParty + "')");

                    cmd.CommandText = sql;
                    cmd.Parameters.Add("@PartyName", SqlDbType.NVarChar).Value = ilist.PartyName;
                    cmd.Parameters.Add("@BillingAddress", SqlDbType.NVarChar).Value = ilist.BillingAddress;
                    cmd.Parameters.Add("@ShippingAddress", SqlDbType.NVarChar).Value = ilist.ShippingAddress;
                    cmd.Parameters.Add("@BankHolderName", SqlDbType.NVarChar).Value = ilist.BankHolderName;
                    cmd.Parameters.Add("@BankName", SqlDbType.NVarChar).Value = ilist.BankName;
                    cmd.Parameters.Add("@BankBranch", SqlDbType.NVarChar).Value = ilist.BankBranch;


                    int PartyId = Convert.ToInt32(cmd.ExecuteScalar());

                    cmd.Dispose();
                    con.Close();

                    if (PartyId > 0)
                    {
                        comman.id = PartyId;
                        comman.Code = 201;
                        comman.Message = "Record has been saved successfully.";
                        JavaScriptSerializer js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;



                    }
                    else
                    {
                        comman.Code = 410;
                        comman.Message = "Problem has been occurred while submitting your data.";
                        JavaScriptSerializer js = new JavaScriptSerializer();
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }

                }


            }
            catch (SqlException ex)
            {

                if (ex.Number == 2601 || ex.Number == 2627)
                {
                    comman.Code = 405;
                    comman.Message = "Cannot insert duplicate values..";
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
                    Context.Response.Write(js.Serialize(comman));
                }
                else
                {
                    comman.Code = 410;
                    comman.Message = "Problem has been occurred while submitting your data.";
                    JavaScriptSerializer js = new JavaScriptSerializer();
                    js.MaxJsonLength = Int32.MaxValue;
                    Context.Response.Write(js.Serialize(comman));
                }

            }



        }

