                                            " YarnRequirementID = '" + id + "', YarnMaterialID = '" + each.YarnMaterialID + "', YarnColorID = '" + each.YarnColorID + "', CompanyName = '" + each.CompanyName + "', " +
                                            " CompanyColourCode = '" + each.CompanyColourCode + "', NoofBoxes = '" + each.NoofBoxes + "' where YarnRequirementDetailID = '" + each.YarnRequirementDetailID + "'  ");

                                        cmd.CommandText = sqls;
                                        cmd.ExecuteNonQuery();
                                    }



