        {

            var request = HttpContext.Current.Request;
            YarnPOMasterResponse ilistColorMatchingForm = new YarnPOMasterResponse();

            List<YarnPOMaster> listDesignEntryForm = new List<YarnPOMaster>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();

            YarnPOMaster ilist = new YarnPOMaster();
            ilist.YarnPODetailID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnPODetailID"]);

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                //cmd.CommandText = " select * from YarnPODetails where YarnPOID = '" + ilist.YarnPOID + "'  " +
                //    "   AND YarnMaterialID = '" + ilist.YarnMaterialID + "'  and YarnColorID = '" + ilist.YarnColorID + "' " +
                //    " AND YarnPODetailID NOT IN (select YarnPODetailIDCompanyCode from YarnInwardMaster where YarnPOID = '" + ilist.YarnPOID + "' )";


                cmd.CommandText = "select YPD.Qty, ISNULL(YIM.TotalWeight,0) as TotalWeight, (YPD.Qty - ISNULL(YIM.TotalWeight,0)) as PendingWeight  from YarnPODetails YPD" +
                    " LEFT JOIN (" +
                    " select SUM(TotalWeight) as TotalWeight, YarnPODetailIDCompanyCode from YarnInwardMaster where YarnPODetailIDCompanyCode = '" + ilist.YarnPODetailID + "'   " +
                    " GROUP BY YarnPODetailIDCompanyCode" +
                    " ) YIM ON YIM.YarnPODetailIDCompanyCode = YPD.YarnPODetailID" +
                    " where YPD.YarnPODetailID = '" + ilist.YarnPODetailID + "'   ";


                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnPOMaster condition = new YarnPOMaster();
                        condition.TotalQty = Convert.ToDecimal(rdr["Qty"].ToString());
                        condition.TotalWeight = Convert.ToDecimal(rdr["TotalWeight"].ToString());
                        condition.PendingWeight = Convert.ToDecimal(rdr["PendingWeight"].ToString());
                        listDesignEntryForm.Add(condition);

                    }



                    rdr.Close();
                    cmd.Dispose();

                    ilistColorMatchingForm.Code = 200;
                    ilistColorMatchingForm.Message = "Success";
                    ilistColorMatchingForm.listYarnPOMaster = listDesignEntryForm;
                }
                else
                {
                    ilistColorMatchingForm.Code = 105;
                    ilistColorMatchingForm.Message = "Opps! Purchase Order Not Exist.";
                    ilistColorMatchingForm.listYarnPOMaster = listDesignEntryForm;
                }
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(ilistColorMatchingForm));
            return;


        }

