        public void getYarnInwardMaster()
        {
            JavaScriptSerializer js;
            List<YarnInwardMaster> listUser = new List<YarnInwardMaster>();
            YarnInwardMasterResponce response = new YarnInwardMasterResponce();

            var request = HttpContext.Current.Request;
            YarnInwardMaster ilist = new YarnInwardMaster();

            ilist.SearchRequirementNo = HttpContext.Current.Request.Params["SearchRequirementNo"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];


            if (ilist.SearchRequirementNo != "")
            {
                ilist.SearchRequirementNo = " and (YIM.ChallanNo LIKE'%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%' or YPO.SupplierPartyName LIKE '%" + HttpContext.Current.Request.Params["SearchRequirementNo"] + "%'  ) ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                //cmd.CommandText = "select PM.* from PartyMaster PM LEFT JOIN CompanyMaster CM ON PM.CompanyId = CM.CompanyId where CM.is_default = '1' and PM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " and PM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1) order by PM.PartyId desc OFFSET " + ilist.startFrom.ToString() + " ROWS FETCH NEXT 10 ROWS ONLY";
                //cmd.CommandText = "SELECT * FROM  ( " +
                //    " select ROW_NUMBER() OVER (ORDER BY YIM.YarnInwardID desc ) row_num,   " +
                //    "  YIM.*, YPO.ShippedToPartyName, YPO.SupplierPartyName, YPO.CompanyPartyName, YPO.SupplierMobileNo, YPO.ShippedToBillingAddress," +
                //    " YMM.YarnMaterial, YCM.YarnColor, YPD.CompanyCode, GM.GodownTitle, " +
                //    " YPO.BillToPartyName, YPO.GodownTitle as 'YarnGodownTitle', GM.GodownTitle, " +
                //    " CASE WHEN YPO.GodownTitle = GM.GodownTitle THEN 'SAME' ELSE 'GODOWN CHANGE' END AS 'GODOWNCHANGE'" +
                //    " from YarnInwardMaster YIM" +
                //    " LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID" +
                //    " LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID =  YCM.YarnColorID " +
                //    " LEFT JOIN YarnPODetails YPD ON YIM.YarnPODetailIDCompanyCode =  YPD.YarnPODetailID " +
                //    " LEFT JOIN GodownMaster GM ON YIM.GodownID = GM.GodownID" +
                //    " LEFT JOIN (select YPM.YarnPOID, SPPM.PartyName as 'ShippedToPartyName', SPM.PartyName as 'SupplierPartyName'," +
                //    " CPM.PartyName as 'CompanyPartyName', SPM.MobileNo as 'SupplierMobileNo', BPM.PartyName as 'BillToPartyName', " +
                //    " SPM.MobileNo as 'SupplierMobileNo', GM.GodownTitle, GM.GodownAddress," +
                //    "CASE WHEN SPPM.ShippingAddress IS NULL THEN SPPM.BillingAddress ELSE SPPM.ShippingAddress END as 'ShippedToBillingAddress'" +
                //    " from YarnPOMaster YPM" +
                //    " LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId" +
                //    " LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId" +
                //    " LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId" +
                //    " LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId" +
                //    " LEFT JOIN GodownMaster GM ON GM.GodownID = YPM.GodownID) as YPO ON YIM.YarnPOID = YPO.YarnPOID" +
                //    " where YIM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                //    " AND YIM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                //    " AND YIM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " +
                //    " " + ilist.SearchRequirementNo + " " +
                //    " ) as t1  WHERE t1.row_num between " + (Convert.ToInt32(ilist.startFrom) + 1) + " and " + (Convert.ToInt32(ilist.startFrom) + 30) + "  " +
                //    " order by t1.YarnInwardID desc   ";



                cmd.CommandText = " SELECT * FROM " +
                    " (  " +
                    " 	select ROW_NUMBER() OVER (ORDER BY YIM.YarnInwardID desc ) row_num,     " +
                    " 	YIM.*, YPO.ShippedToPartyName, YPO.SupplierPartyName, YPO.CompanyPartyName," +
                    " 	YPO.SupplierMobileNo, YPO.ShippedToBillingAddress, YMM.YarnMaterial, " +
                    " 	YCM.YarnColor, YPD.CompanyCode, YPD.PONo,  YPO.BillToPartyName, YPO.GodownTitle as 'YarnGodownTitle', GM.GodownTitle, GM.GodownAddress, " +
                    " 	CASE WHEN YPO.GodownTitle = GM.GodownTitle THEN 'SAME' ELSE 'GODOWN CHANGE' END AS 'GODOWNCHANGE'," +
                    "   ISNULL(YID.Total,0) AS TotalBarcode " +
                    " 	from YarnInwardMaster YIM " +
                    " 	LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID " +
                    " 	LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID =  YCM.YarnColorID  " +
                    " 	LEFT JOIN (select YPD.YarnPODetailID, YPD.CompanyCode, YPM.PONo" +
                    "   from YarnPODetails YPD" +
                    "   LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YPD.YarnPOID) YPD ON YIM.YarnPODetailIDCompanyCode =  YPD.YarnPODetailID  " +
                    " 	LEFT JOIN GodownMaster GM ON YIM.GodownID = GM.GodownID " +
                    "   LEFT JOIN " +
                    "   (" +
                    "   	select DISTINCT(YarnInwardID), COUNT(BarcodeNo) as Total" +
                    " 	    from YarnInwardDetail " +
                    "   	where BarcodeNo IS NOT NULL" +
                    " 	    Group by YarnInwardID" +
                    "   ) YID ON YIM.YarnInwardID =  YID.YarnInwardID " +
                    " 	LEFT JOIN " +
                    " 	(" +
                    " 		select YPM.YarnPOID, SPPM.PartyName as 'ShippedToPartyName', " +
                    " 		SPM.PartyName as 'SupplierPartyName', CPM.PartyName as 'CompanyPartyName', " +
