            List<YarnMaterialMaster> listYarnMaterialMaster = new List<YarnMaterialMaster>();
            List<YarnColorMaster> listYarnColorMaster = new List<YarnColorMaster>();
            List<UserAccountMaster> listUserAccountMaster = new List<UserAccountMaster>();
            List<YarnOutwardMaster> listYarnOutwardMaster = new List<YarnOutwardMaster>();
            List<GodownMaster> listGodownMaster = new List<GodownMaster>();
            List<YarnInwardMaster> YarnInwardMasterData = new List<YarnInwardMaster>();
            //SalesOrderResponseClass salesOrderResponseData = new SalesOrderResponseClass();
            int YarnOutwardID = 0;
            int GodownID = 0;
            string abc = HttpContext.Current.Request.Params["YarnOutwardID"] ?? string.Empty;
            if (abc != "")
            {
                string lastCharacter = abc.Substring(abc.Length - 6);
                if (lastCharacter != "%3d%3d")
                {
                    string InvoiceId = HttpContext.Current.Request.Params["YarnOutwardID"].Replace("==", "") + "%3d%3d";
                    YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
                }
                else
                {
                    YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnOutwardID"])));
                }
            }

            string CompanyName = "";
            string YarnMaterial = "";
            string YarnColor = "";
            string YarnInwardDetails = "";
            //YarnOutwardMasterResponce ilist = new YarnOutwardMasterResponce();
            //ilist.YarnInwardDetailIDs = HttpContext.Current.Request.Params["YarnInwardDetailID"];

            //Upload Cate Master
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                //Party Master
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                if (YarnOutwardID > 0)
                {
                    cmd.CommandText = @"select * from YarnOutwardMaster Where YarnOutwardID= " + YarnOutwardID + "";
                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();
                    if (rdr.HasRows)
                    {
                        while (rdr.Read())
                        {
                            YarnInwardMaster condition = new YarnInwardMaster();
                            condition.GodownID = Convert.ToInt32(rdr["GodownID"].ToString());
                            condition.PartyId = Convert.ToInt32(rdr["PartyId"].ToString());
                            YarnInwardMasterData.Add(condition);
                        }

                    }
                    rdr.Close();
                    GodownID = YarnInwardMasterData[0].GodownID;
                }

            }

            using (SqlConnection con = new SqlConnection(cs))
            {
                //Party Master
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                cmd.CommandText = @"select * from PartyMaster where SundryParty = 1 and IsActiveParty = 1 and CompanyId = (select CompanyId from CompanyMaster where is_default = 1)";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();
                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PartyMaster condition = new PartyMaster();
                        condition.PartyId = Convert.ToInt32(rdr["PartyId"].ToString());
                        condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                        listPartyMaster.Add(condition);
                    }

                }

                rdr.Close();

                //Yarn Material
                cmd.CommandText = @"SELECT YIM.YarnMaterialID,YMM.YarnMaterial
                                            FROM YarnInwardMaster YIM
                                            LEFT JOIN YarnMaterialMaster YMM 
                                                ON YIM.YarnMaterialID = YMM.YarnMaterialID

                                            LEFT JOIN (
                                                SELECT YarnInwardID, COUNT(*) AS InStock
                                                FROM YarnInwardDetail
                                                GROUP BY YarnInwardID
                                            ) INWARD ON YIM.YarnInwardID = INWARD.YarnInwardID

                                            LEFT JOIN (
                                                SELECT 
                                                    YOD.YarnMaterialID,
                                                    YOD.YarnColorID,
                                                    SUM(YOD.NoOfBox) AS OutStock
                                                FROM YarnOutwardDetail YOD
                                                GROUP BY YOD.YarnMaterialID, YOD.YarnColorID
                                            ) OUTWARD ON YIM.YarnMaterialID = OUTWARD.YarnMaterialID
                                            GROUP BY YIM.YarnMaterialID,YMM.YarnMaterial

                                            HAVING ISNULL(SUM(INWARD.InStock),0) > 0
                                   ";
                SqlDataReader rdr2 = cmd.ExecuteReader();

                if (rdr2.HasRows)
                {
                    while (rdr2.Read())
                    {
                        YarnMaterialMaster condition = new YarnMaterialMaster();
                        condition.YarnMaterialID = Convert.ToInt32(rdr2["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr2["YarnMaterial"].ToString().ToUpper();
                        listYarnMaterialMaster.Add(condition);
                    }

                }
                rdr2.Close();


                //Yarn Color
                cmd.CommandText = @"select YPD.YarnColorID , YCM.YarnColor ,YPD.CompanyCode As YarnColorCode  from YarnPOMaster YPO 
                                            LEFT JOIN YarnPODetails YPD ON YPD.YarnPOID = YPO.YarnPOID
                                            LEFT JOIN YarnColorMaster YCM ON YCM.YarnColorID = YPd.YarnColorID";
                SqlDataReader rdr3 = cmd.ExecuteReader();
                if (rdr3.HasRows)
                {
                    while (rdr3.Read())
                    {
                        YarnColorMaster condition = new YarnColorMaster();
                        condition.YarnColorID = Convert.ToInt32(rdr3["YarnColorID"].ToString());
                        condition.YarnColor = rdr3["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr3["YarnColorCode"].ToString().ToUpper();
                        listYarnColorMaster.Add(condition);
                    }

                }

                rdr3.Close();

                //Company Master
                cmd.CommandText = @"
                                    select PartyId, PartyName from PartyMaster where PartyId in
                                    (
	                                    select DISTINCT(BillToPartyID) from YarnPOMaster 
	                                    where YarnPOID in
	                                    (
		                                    select DISTINCT(YarnPOID) from YarnInwardMaster where CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
	                                    )
                                    )
                                   ";

                SqlDataReader rdr4 = cmd.ExecuteReader();
                if (rdr4.HasRows)
                {
                    while (rdr4.Read())
                    {
                        PartyMaster condition = new PartyMaster();
                        condition.PartyId = Convert.ToInt32(rdr4["PartyId"].ToString());
                        condition.PartyName = rdr4["PartyName"].ToString().ToUpper();
                        listCompanyMaster.Add(condition);
                    }

                }
                rdr4.Close();

                //Godown Manager
                cmd.CommandText = @"select * from UserAccountMaster where UserRole = 'Watchman' and AllowLogin = 1";
                SqlDataReader rdr5 = cmd.ExecuteReader();
                if (rdr5.HasRows)
                {
                    while (rdr5.Read())
                    {
                        UserAccountMaster condition = new UserAccountMaster();
                        condition.UserAccountId = Convert.ToInt32(rdr5["UserAccountId"].ToString());
                        condition.UserAccountName = rdr5["UserAccountName"].ToString().ToUpper();
                        listUserAccountMaster.Add(condition);
                    }
                }


                rdr5.Close();




                //Godown Master
                cmd.CommandText = @"SELECT GM.* FROM GodownMaster GM INNER JOIN CompanyMaster CM  ON GM.CompanyId = CM.CompanyId WHERE GM.IsActive = 1 AND CM.is_default = 1;                         ";


                SqlDataReader rdr6 = cmd.ExecuteReader();
                if (rdr6.HasRows)
                {
                    while (rdr6.Read())
                    {
                        GodownMaster condition = new GodownMaster();
                        condition.GodownID = Convert.ToInt32(rdr6["GodownID"].ToString());
                        condition.GodownTitle = rdr6["GodownTitle"].ToString().ToUpper();
                        condition.GodownAddress = rdr6["GodownAddress"].ToString().ToUpper();
                        condition.IsDefault = Convert.ToInt32(rdr6["IsDefault"].ToString());
                        listGodownMaster.Add(condition);
                    }
                }


                rdr6.Close();





                //YarnOutWard
                cmd.CommandText = @"
                                     select (ISNULL(MAX(OutwardListNo),0) +1 ) as OutwardListNo from YarnOutwardMaster 
                                    where FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)
                                    and CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
                                   ";


                SqlDataReader rdr7 = cmd.ExecuteReader();
                if (rdr7.HasRows)
                {
                    while (rdr7.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.OutwardListNo = Convert.ToInt32(rdr7["OutwardListNo"].ToString());
                        listYarnOutwardMaster.Add(condition);
                    }
                }


                rdr7.Close();

                listYarnOutwardMasterResponce.Code = 200;
                listYarnOutwardMasterResponce.Message = "Success";
                listYarnOutwardMasterResponce.listPartyMaster = listPartyMaster;
                listYarnOutwardMasterResponce.listYarnMaterialMaster = listYarnMaterialMaster;
                listYarnOutwardMasterResponce.listYarnColorMaster = listYarnColorMaster;
                listYarnOutwardMasterResponce.listCompanyMaster = listCompanyMaster;
                listYarnOutwardMasterResponce.listUserAccountMaster = listUserAccountMaster;
                listYarnOutwardMasterResponce.listGodownMaster = listGodownMaster;
                listYarnOutwardMasterResponce.listYarnOutwardMaster = listYarnOutwardMaster;
                listYarnOutwardMasterResponce.YarnInwardMasterData = YarnInwardMasterData;
                con.Close();
            }


            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(listYarnOutwardMasterResponce));
            return;


        }

        // View Yarn Out Ward
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void getYarnOutwardMaster()
        {
            JavaScriptSerializer js;
            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();
            var request = HttpContext.Current.Request;
            YarnOutwardMaster ilist = new YarnOutwardMaster();
            ilist.GodownID = Convert.ToInt32(HttpContext.Current.Request.Params["GodownID"]);
            ilist.BillToPartyID = Convert.ToInt32(HttpContext.Current.Request.Params["BillToPartyID"]);
            ilist.YarnMaterialID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnMaterialID"]);
            ilist.YarnColorID = Convert.ToInt32(HttpContext.Current.Request.Params["YarnColorID"]);
            ilist.YarnInwardDetailIDss = HttpContext.Current.Request.Params["YarnInwardDetailIDss"];
            ilist.SiftGodownLocationId = HttpContext.Current.Request.Params["SiftGodownLocationId"];
            string CompanyName = "";
            if (ilist.BillToPartyID != 0)
            {
                CompanyName = " and t1.BillToPartyID = " + ilist.BillToPartyID + " ";
            }
            string YarnMaterial = "";
            if (ilist.YarnMaterialID != 0)
            {
                YarnMaterial = " and t1.YarnMaterialID = " + ilist.YarnMaterialID + " ";
            }
            string YarnColor = "";
            if (ilist.YarnColorID != 0)
            {
                YarnColor = " and t1.YarnColorID = " + ilist.YarnColorID + " ";
            }


            string YarnInwardDetails = "";
            //if (ilist.YarnInwardDetailIDss != "")
            //{
            //    YarnInwardDetails = " and YarnInwardDetailID not in (" + ilist.YarnInwardDetailIDss + ") ";
            //}


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;



                if (ilist.SiftGodownLocationId != "")
                {

                    cmd.CommandText = @"select (t2.Stock) AS Stock, 
                                        t2.BillToPartyID, t2.CompanyName, t2.YarnMaterialID,
                                        t2.YarnMaterial, t2.YarnColorID, t2.YarnColor,
                                        t2.YarnColorCode from
                                        (
	                                        select CASE 
		                                        WHEN (t1.Stock - ISNULL(t2.Stock,0)) < 0 THEN 0
		                                        ELSE (t1.Stock - ISNULL(t2.Stock,0))
	                                        END AS Stock, t1.BillToPartyID, t1.CompanyName, t1.YarnMaterialID, t1.YarnMaterial, 
	                                        t1.YarnColorID, t1.YarnColor,
	                                        t1.YarnColorCode from 
	                                        (
		                                        select ISNULL(SUM(Stock),0) as Stock, t1.BillToPartyID, t1.CompanyName,
		                                        t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode from
		                                        (
			                                        select  YIM.YarnInwardID, YIM.YarnPOID, YPM.BillToPartyID, YPM.PartyName as 'CompanyName',
			                                        YIM.YarnMaterialID, YMM.YarnMaterial, YIM.YarnColorID, YCM.YarnColor, YCM.YarnColorCode , YIDD.Stock
			                                        from YarnInwardMaster YIM
			                                        LEFT JOIN 
			                                        (
				                                        select YPM.YarnPOID, YPM.BillToPartyID, PM.PartyName from YarnPOMaster YPM
				                                        LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
			                                        )YPM ON YIM.YarnPOID = YPM.YarnPOID
			                                        LEFT JOIN YarnMaterialMaster YMM ON YIM.YarnMaterialID = YMM.YarnMaterialID
			                                        LEFT JOIN YarnColorMaster YCM ON YIM.YarnColorID = YCM.YarnColorID
			                                        LEFT JOIN 
			                                        (
				                                        select COUNT(*) as Stock, YarnInwardID from YarnInwardDetail 
						                                        where GodownLocationID in (select GodownLocationID from GodownLocationMaster where GodownID = '" + ilist.GodownID + @"')
						                                        group by YarnInwardID
			                                        ) YIDD ON YIM.YarnInwardID = YIDD.YarnInwardID
		                                        ) as t1
		                                        where (1=1) " + CompanyName + @" " + YarnMaterial + @" " + YarnColor + @"   
		                                        group by t1.BillToPartyID, t1.CompanyName,
		                                        t1.YarnMaterialID, t1.YarnMaterial, t1.YarnColorID, t1.YarnColor, t1.YarnColorCode  
	                                        ) as t1 
	                                        LEFT JOIN 
	                                        (
		                                        select SUM(t1.InputNoOfBox) as Stock,
		                                        t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID
		                                        from
		                                        (
			                                        SELECT
				                                        GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID,  ISNULL(SUM(InputNoOfBox),0) as InputNoOfBox
			                                        FROM (
				                                        SELECT * FROM (VALUES
					                                        " + ilist.SiftGodownLocationId + @"
				                                        ) AS V ( GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID, InputNoOfBox)
			                                        ) X 
			                                        GROUP BY GodownLocationID, BillToPartyID, YarnMaterialID, YarnColorID
		                                        ) as t1
		                                        group by t1.BillToPartyID, t1.YarnMaterialID, t1.YarnColorID
	                                        ) as t2
	                                        ON  t1.BillToPartyID = t2.BillToPartyID
	                                        AND t1.YarnMaterialID = t2.YarnMaterialID
	                                        AND t1.YarnColorID = t2.YarnColorID
                                        ) as t2
                                        WHERE t2.Stock > 0";


                }
                else
                {

                    cmd.CommandText = @"
                                    SELECT 
	                                    (t1.Stock - ISNULL(YOD.Stock, 0)) AS Stock, 
	                                    t1.BillToPartyID,  t1.CompanyName,  t1.YarnMaterialID, t1.YarnMaterial,  t1.YarnColorID,  t1.YarnColor, t1.YarnColorCode
                                    FROM 
                                    (
                                        SELECT 
                                            ISNULL(SUM(t1.Stock),0) as Stock,  t1.BillToPartyID,  t1.CompanyName, t1.YarnMaterialID, 
                                            t1.YarnMaterial,  t1.YarnColorID,  t1.YarnColor,  t1.YarnColorCode 
                                        FROM
                                        (
                                            SELECT  
                                                YIM.YarnInwardID,  YIM.YarnPOID,  YPM.BillToPartyID,  YPM.PartyName AS CompanyName,
                                                YIM.YarnMaterialID,  YMM.YarnMaterial,  YIM.YarnColorID,  YCM.YarnColor,  YCM.YarnColorCode, 
                                                YIDD.Stock
                                            FROM YarnInwardMaster YIM
                                            LEFT JOIN 
                                            (
                                                SELECT YPM.YarnPOID, YPM.BillToPartyID, PM.PartyName 
                                                FROM YarnPOMaster YPM
                                                LEFT JOIN PartyMaster PM 
                                                    ON YPM.BillToPartyID = PM.PartyId
                                            ) YPM 
                                                ON YIM.YarnPOID = YPM.YarnPOID
                                            LEFT JOIN YarnMaterialMaster YMM 
                                                ON YIM.YarnMaterialID = YMM.YarnMaterialID
                                            LEFT JOIN YarnColorMaster YCM 
                                                ON YIM.YarnColorID = YCM.YarnColorID
                                            LEFT JOIN 
                                            (
                                                SELECT COUNT(*) AS Stock, YarnInwardID 
                                                FROM YarnInwardDetail 
                                                WHERE GodownLocationID IN 
                                                (
                                                    SELECT GodownLocationID 
                                                    FROM GodownLocationMaster 
                                                    WHERE GodownID = '" + ilist.GodownID + @"'
                                                )
                                                " + YarnInwardDetails + @" 
                                                GROUP BY YarnInwardID
                                            ) YIDD 
                                                ON YIM.YarnInwardID = YIDD.YarnInwardID
                                        ) AS t1
                                        where (1=1) " + CompanyName + @" " + YarnMaterial + @" " + YarnColor + @"
                                        GROUP BY  t1.BillToPartyID,  t1.CompanyName, t1.YarnMaterialID,  t1.YarnMaterial, 
                                            t1.YarnColorID,  t1.YarnColor,  t1.YarnColorCode  
                                    ) AS t1
                                    LEFT JOIN 
                                    (
	                                    select SUM(YOD.NoOfBox) as Stock, YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID from YarnOutwardDetail YOD
                                    LEFT JOIN YarnOutwardMaster YOM ON YOD.YarnOutwardID = YOM.YarnOutwardID
                                    where YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
                                    group by YOD.BillToPartyID, YOD.YarnMaterialID, YOD.YarnColorID 
                                    ) YOD ON  t1.BillToPartyID = YOD.BillToPartyID   AND
                                        t1.YarnMaterialID = YOD.YarnMaterialID
                                    AND t1.YarnColorID = YOD.YarnColorID
                                    where (t1.Stock - ISNULL(YOD.Stock, 0)) > 0";
                }


                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnOutwardMaster condition = new YarnOutwardMaster();
                        condition.BillToPartyID = Convert.ToInt32(rdr["BillToPartyID"].ToString());
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.YarnColorCode = rdr["YarnColorCode"].ToString().ToUpper();
                        condition.CompanyName = rdr["CompanyName"].ToString().ToUpper();
                        condition.Stock = Convert.ToInt32(rdr["Stock"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }



            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
