                                        FROM (SELECT 
                                                ISNULL(SUM(t1.Stock), 0) as Stock, 
                                                t1.BillToPartyID, 
                                                t1.CompanyName, 
                                                t1.YarnMaterialID, 
                                                t1.YarnMaterial, 
                                                t1.YarnColorID, 
                                                t1.YarnColor, 
                                                t1.CompanyCode,
                                                t1.YarnInterchangeID, 
