        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void GetDisplayYarnoutwardScanMaster()
        {

            JavaScriptSerializer js;
            List<YarnOutwardMaster> listUser = new List<YarnOutwardMaster>();
            YarnOutwardMasterResponce response = new YarnOutwardMasterResponce();

            var request = HttpContext.Current.Request;
            YarnOutwardMaster ilist = new YarnOutwardMaster();
            string Status = HttpContext.Current.Request.Params["Status"];
            ilist.SearchRequirementNo = HttpContext.Current.Request.Params["SearchRequirementNo"];
            ilist.startFrom = HttpContext.Current.Request.Params["startFrom"];

            if (ilist.SearchRequirementNo != "")
            {
                ilist.SearchRequirementNo = " and (YOM.OutwardListNo LIKE '%" + ilist.SearchRequirementNo + "%' OR PM.PartyName LIKE '%" + ilist.SearchRequirementNo + "%' or PM.MobileNo LIKE '%" + ilist.SearchRequirementNo + "%'  ) ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            if (Status == "Pending")
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = System.Data.CommandType.Text;

                    cmd.CommandText = @"
                        SELECT * FROM (
                                select ROW_NUMBER() OVER (ORDER BY YOM.YarnOutwardID desc ) row_num,
                                Yom.YarnOutwardID,Yom.OutwardListNo,YOM.DateAndTime,PM.PartyName,PM.MobileNo, ISNULL(YD.TotalNoOfBox,0) AS TotalNoOfBox  FROM YarnOutwardMaster YOM
                                LEFT JOIN PartyMaster PM  ON YOM.PartyId = PM.PartyId
                                LEFT JOIN GodownMaster GM ON YOM.GodownID = GM.GodownID 
                                LEFT JOIN (SELECT YarnOutwardID, SUM(NoOfBox) AS TotalNoOfBox FROM YarnOutwardDetail  GROUP BY YarnOutwardID ) YD 
                                    ON YOM.YarnOutwardID = YD.YarnOutwardID
                                WHERE YOM.IsScanStutas = 0 AND YOM.FinancialYearID = (SELECT FinancialYearID FROM FinancialYearMaster WHERE IsDefault = 1)         
                                AND YOM.CompanyId = (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1)
                                    " + ilist.SearchRequirementNo + @"
                                    AND YOM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @"
                        ) A  WHERE A.row_num between " + (Convert.ToInt32(ilist.startFrom) + 1) + @" and " + (Convert.ToInt32(ilist.startFrom) + 30) + @"
                                                        order by A.YarnOutwardID desc";

                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();

                    if (rdr.HasRows)
                    {
                        while (rdr.Read())
                        {
                            YarnOutwardMaster condition = new YarnOutwardMaster();
                            condition.YarnOutwardID = Convert.ToInt32(rdr["YarnOutwardID"].ToString());
                            condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                            condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                            condition.OutwardListNo = Convert.ToInt32(rdr["OutwardListNo"].ToString());
                            condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                            condition.MobileNo = rdr["MobileNo"].ToString();
                            condition.BoxNo = rdr["TotalNoOfBox"].ToString();
                            listUser.Add(condition);
                        }
                    }

                    rdr.Close();
                    cmd.Dispose();
                    con.Close();
                }
            }
            else
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.CommandType = System.Data.CommandType.Text;

                    cmd.CommandText = @"
                        SELECT * FROM (
                                select ROW_NUMBER() OVER (ORDER BY YOM.YarnOutwardID desc ) row_num,
                                Yom.YarnOutwardID,Yom.OutwardListNo,YOM.DateAndTime,PM.PartyName,PM.MobileNo, ISNULL(YD.TotalNoOfBox,0) AS TotalNoOfBox  FROM YarnOutwardMaster YOM
                                LEFT JOIN PartyMaster PM  ON YOM.PartyId = PM.PartyId
                                LEFT JOIN GodownMaster GM ON YOM.GodownID = GM.GodownID 
                                LEFT JOIN (SELECT YarnOutwardID, SUM(NoOfBox) AS TotalNoOfBox FROM YarnOutwardDetail  GROUP BY YarnOutwardID ) YD 
                                    ON YOM.YarnOutwardID = YD.YarnOutwardID
                                WHERE YOM.IsScanStutas = 1 AND YOM.FinancialYearID = (SELECT FinancialYearID FROM FinancialYearMaster WHERE IsDefault = 1)         
                                AND YOM.CompanyId = (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1)
                                    " + ilist.SearchRequirementNo + @"
                                    AND YOM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @"
                        ) A  WHERE A.row_num between " + (Convert.ToInt32(ilist.startFrom) + 1) + @" and " + (Convert.ToInt32(ilist.startFrom) + 30) + @"
                                                        order by A.YarnOutwardID desc";

                    con.Open();
                    SqlDataReader rdr = cmd.ExecuteReader();

                    if (rdr.HasRows)
                    {
                        while (rdr.Read())
                        {
                            YarnOutwardMaster condition = new YarnOutwardMaster();
                            condition.YarnOutwardID = Convert.ToInt32(rdr["YarnOutwardID"].ToString());
                            condition.DateAndTime = Convert.ToDateTime(rdr["DateAndTime"].ToString());
                            condition.DateAndTimes = Convert.ToDateTime(rdr["DateandTime"].ToString()).ToString("dd-MM-yyyy");
                            condition.OutwardListNo = Convert.ToInt32(rdr["OutwardListNo"].ToString());
                            condition.PartyName = rdr["PartyName"].ToString().ToUpper();
                            condition.MobileNo = rdr["MobileNo"].ToString();
                            condition.BoxNo = rdr["TotalNoOfBox"].ToString();
                            listUser.Add(condition);
                        }
                    }

                    rdr.Close();
                    cmd.Dispose();
                    con.Close();
                }
            }




            response.Code = 200;
            response.Message = "Success";
            response.listYarnOutwardMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void GetYarnOutwardMasterScanPaggination()
        {
            JavaScriptSerializer js;
            List<PagginationMaster> listUser = new List<PagginationMaster>();
            PagginationMasterResponse response = new PagginationMasterResponse();

            var request = HttpContext.Current.Request;
            PagginationMaster ilist = new PagginationMaster();

            ilist.SearchString = HttpContext.Current.Request.Params["SearchRequirementNo"];


            string SearchString = "";
            if (ilist.SearchString != "")
            {
                SearchString = " and (UAM.UserAccountName LIKE '%" + ilist.SearchString + "%' OR UAM.UserAccountMobileNo LIKE '%" + ilist.SearchString + "%' or YOM.OutwardListNo LIKE '%" + ilist.SearchString + "%') ";
            }


            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;

                cmd.CommandText = @"    
                                    select COUNT(*) as Total, CAST(ceiling(CAST(COUNT(*) AS DECIMAL(7,2) ) / CAST(30 AS DECIMAL(7,2) )) AS DECIMAL(7,0)) as Paggination from (
	                                select ROW_NUMBER() OVER (ORDER BY YOM.YarnOutwardID desc ) row_num, 
	                                YOM.*, UAM.UserAccountName, UAM.UserAccountMobileNo from YarnOutwardMaster YOM
	                                LEFT JOIN UserAccountMaster UAM ON YOM.GodownManagerUserAccountId = UAM.UserAccountId
	                                where YOM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)
		                                and YOM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)
                                            AND YOM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + @" 

                                        " + SearchString + @"
                                ) as t1 
                                ";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        PagginationMaster condition = new PagginationMaster();
                        condition.Total = Convert.ToInt32(rdr["Total"].ToString());
                        condition.Paggination = Convert.ToInt32(rdr["Paggination"].ToString());
                        listUser.Add(condition);
                    }
                }

                rdr.Close();
                cmd.Dispose();
                con.Close();
            }

            response.Code = 1;
            response.Message = "Success";
            response.listPagginationMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void GetYarnOutwardScan()
        {
            var request = HttpContext.Current.Request;
            List<YarnOutwardMaster> listPartyMaster = new List<YarnOutwardMaster>();

            int YarnOutwardID = 0;
            int ChallanNo = 0;
            string abc = request.Params["YarnOutwardID"];
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = request.Params["YarnOutwardID"].Replace("==", "") + "%3d%3d";
                YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(request.Params["YarnOutwardID"])));
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;

                cmd.CommandText = @"SELECT ISNULL(MAX(ChallanNo),0) + 1 AS ChallanNo FROM YARNOUTWARDScanMaster";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    ChallanNo = Convert.ToInt32(rdr["ChallanNo"]);

                }
            }


            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;

                cmd.CommandText = @"SELECT                            
                            Pm.PartyId,
                            PM.PartyName,
							PM1.PartyId AS YarnCompanyId,
                            PM1.PartyName AS YarnCompany,
                            Pm.BillingAddress AS Address,
                            YMM.YarnMaterialID AS YarnMaterialID,
                            YMM.YarnMaterial AS YarnMaterial,
                            YCM.YarnColorID AS YarnColorID,
                            YCM.YarnColor AS YarnColour,
                            YCM.YarnColorCode AS Code,
		                    GLM.GodownLocationID,
                            GLM.LocationTitle AS Location,
                            N.BoxNo
                            FROM YarnOutwardDetail YOD
                            INNER JOIN YarnOutwardMaster YM 
                                ON YM.YarnOutwardID = YOD.YarnOutwardID
                            LEFT JOIN PartyMaster PM 
                                ON YM.PartyId = PM.PartyId
                            LEFT JOIN PartyMaster PM1 ON YOD.BillToPartyID = PM1.PartyId
                            LEFT JOIN YarnMaterialMaster YMM  
                                ON YMM.YarnMaterialID = YOD.YarnMaterialID
                            LEFT JOIN YarnColorMaster YCM  
                                ON YCM.YarnColorID = YOD.YarnColorID
                            LEFT JOIN GodownLocationMaster GLM  
                                ON GLM.GodownLocationID = YOD.GodownLocationID
                            CROSS APPLY
                            (
                                SELECT TOP (YOD.NoOfBox)
                                ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS BoxNo
                                FROM master..spt_values
                            ) N
                            WHERE YOD.YarnOutwardID = @YarnOutwardID";

                cmd.Parameters.AddWithValue("@YarnOutwardID", YarnOutwardID);

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    YarnOutwardMaster yarnOutward = new YarnOutwardMaster();
                    yarnOutward.PartyId = Convert.ToInt32(rdr["PartyId"]);
                    yarnOutward.PartyName = (rdr["PartyName"].ToString());
                    yarnOutward.CompanyId = Convert.ToInt32(rdr["YarnCompanyId"].ToString());
                    yarnOutward.CompanyName = rdr["YarnCompany"].ToString();
                    yarnOutward.Address = rdr["Address"].ToString();
                    yarnOutward.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                    yarnOutward.YarnMaterial = rdr["YarnMaterial"].ToString();
                    yarnOutward.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                    yarnOutward.YarnColor = rdr["YarnColour"].ToString();
                    yarnOutward.YarnColorCode = rdr["Code"].ToString();
                    yarnOutward.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"].ToString());
                    yarnOutward.LocationTitle = rdr["Location"].ToString();
                    yarnOutward.BoxNo = (rdr["BoxNo"].ToString());
                    yarnOutward.ChallanNo = ChallanNo;
                    listPartyMaster.Add(yarnOutward);
                }
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;

            Context.Response.Write(js.Serialize(listPartyMaster));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void GetBoxWeight(string BarcodeNo, int YarnMaterial, int YarnColour, int GodownLocationID, int YarnCompany)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            YarnInwardDetail yarnOutward = new YarnInwardDetail();
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer();
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand(@"
                           IF EXISTS (
    SELECT 1 
    FROM YARNOUTWARDScanMasterDetails YOSD
    LEFT JOIN YarnInwardDetail YID ON YOSD.YarnInwardDetailID = YID.YarnInwardDetailID
    LEFT JOIN YarnInwardMaster YM ON YM.YarnInwardID = YID.YarnInwardID
    LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YM.YarnPOID
    LEFT JOIN PartyMaster PM ON PM.PartyId = YPM.BillToPartyID
    WHERE YOSD.BarcodeNo = @BarcodeNo 
      AND YOSD.YarnMaterial = @YarnMaterial 
      AND YOSD.YarnColour = @YarnColour 
      AND YOSD.GodownLocationID = @GodownLocationID
      AND YOSD.YarnCompany = @YarnCompany
)
BEGIN
    SELECT 
        'EXIST' AS Status,
        NULL AS YarnInwardDetailID,
        NULL AS BoxNo,
        NULL AS NetWeight,
        NULL AS BarcodeNo,
        NULL AS GodownLocationID,
        NULL AS YarnInwardID
END
ELSE
BEGIN
    SELECT 
        'OK' AS Status,
        YID.YarnInwardDetailID,
        YID.BoxNo,
        YID.NetWeight,
        YID.BarcodeNo,
        GLM.GodownLocationID,
        GLM.LocationTitle,
        YID.YarnInwardID,
        YMM.YarnMaterialID,
        YMM.YarnMaterial,
        YCM.YarnColorID,
        YCM.YarnColor,
        YCM.YarnColorCode,
        PM.PartyId,
        PM.PartyName
    FROM YarnInwardDetail YID
    LEFT JOIN YarnInwardMaster YM ON YM.YarnInwardID = YID.YarnInwardID
    LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YM.YarnPOID
    LEFT JOIN PartyMaster PM ON PM.PartyId = YPM.BillToPartyID
    LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = YM.YarnMaterialID
    LEFT JOIN YarnColorMaster YCM ON YCM.YarnColorID = YM.YarnColorID
    LEFT JOIN GodownLocationMaster GLM ON GLM.GodownLocationID = YID.GodownLocationID
    WHERE YID.BarcodeNo = @BarcodeNo
      AND YMM.YarnMaterialID = @YarnMaterial
      AND YCM.YarnColorID = @YarnColour
      AND YID.GodownLocationID = @GodownLocationID
      AND YPM.BillToPartyID = @YarnCompany
END
                        ", con);

                cmd.Parameters.AddWithValue("@BarcodeNo", BarcodeNo);
                cmd.Parameters.AddWithValue("@YarnMaterial", YarnMaterial);
                cmd.Parameters.AddWithValue("@YarnColour", YarnColour);
                cmd.Parameters.AddWithValue("@GodownLocationID", GodownLocationID);
                cmd.Parameters.AddWithValue("@YarnCompany", YarnCompany);
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.Read())
                {
                    if (rdr["Status"] != DBNull.Value && rdr["Status"].ToString() == "EXIST")
                    {
                        comman.Code = 410;
                        comman.Message = $"This Box {BarcodeNo} already scanned.";
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                    else
                    {
                        comman.Code = 201;
                        yarnOutward.YarnInwardDetailID = Convert.ToInt32(rdr["YarnInwardDetailID"]);
                        yarnOutward.BoxNo = rdr["BoxNo"].ToString();
                        yarnOutward.NetWeight = Convert.ToDecimal(rdr["NetWeight"]);
                        yarnOutward.BarcodeNo = rdr["BarcodeNo"].ToString();
                        yarnOutward.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"]);
                        yarnOutward.YarnInwardID = Convert.ToInt32(rdr["YarnInwardID"]);
                    }
                }
            }
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(yarnOutward));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateYarnOutwardScan()
        {
            var request = HttpContext.Current.Request;
            List<YarnOutwardMaster> listPartyMaster = new List<YarnOutwardMaster>();

            int YarnOutwardID = 0;
            int ChallanNo = 0;
            int YarnOutwardScanID = 0;
            string abc = request.Params["YarnOutwardID"];
            string lastCharacter = abc.Substring(abc.Length - 6);
            DateTime ChallanDate = Convert.ToDateTime("1990-01-01");
            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = request.Params["YarnOutwardID"].Replace("==", "") + "%3d%3d";
                YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(request.Params["YarnOutwardID"])));
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;

                cmd.CommandText = @"select ChallanNo,YarnOutwardScanID,ChallanDate from YARNOUTWARDScanMaster WHERE YarnOutwardID = @YarnOutwardID;";
                cmd.Parameters.AddWithValue("@YarnOutwardID", YarnOutwardID);
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    ChallanNo = Convert.ToInt32(rdr["ChallanNo"]);
                    YarnOutwardScanID = Convert.ToInt32(rdr["YarnOutwardScanID"]);
                    ChallanDate = rdr.GetDateTime(rdr.GetOrdinal("ChallanDate"));
                }
            }


            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = CommandType.Text;

                cmd.CommandText = @"SELECT 
    PM.PartyId,
    PM.PartyName,

    PM1.PartyId AS YarnCompanyId,
    PM1.PartyName AS YarnCompany,

    PM.BillingAddress AS Address,

    D.YarnMaterial AS YarnMaterialID,
    YMM.YarnMaterial,

    YCM.YarnColorID,
    YCM.YarnColor AS YarnColour,
    YCM.YarnColorCode AS Code,

    GLM.GodownLocationID,
    GLM.LocationTitle AS Location,

    D.YarnInwardDetailID,
    D.BoxNo,
    D.BarcodeNo,
    D.NetWeight

FROM YARNOUTWARDScanMasterDetails D

INNER JOIN YARNOUTWARDScanMaster M
    ON M.YarnOutwardScanID = D.YarnOutwardScanID

INNER JOIN PartyMaster PM
    ON D.PartyId = PM.PartyId

INNER JOIN YarnMaterialMaster YMM
    ON YMM.YarnMaterialID = D.YarnMaterial

INNER JOIN YarnColorMaster YCM
    ON YCM.YarnColorID = D.YarnColour

INNER JOIN GodownLocationMaster GLM
    ON GLM.GodownLocationID = D.GodownLocationID

INNER JOIN PartyMaster PM1
    ON PM1.PartyId =
       (SELECT TOP 1 BillToPartyID 
        FROM YarnOutwardDetail 
        WHERE YarnOutwardID = M.YarnOutwardID)
        WHERE M.YarnOutwardID = @YarnOutwardID";

                cmd.Parameters.AddWithValue("@YarnOutwardID", YarnOutwardID);

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    YarnOutwardMaster yarnOutward = new YarnOutwardMaster();
                    yarnOutward.NetWeight = Convert.ToDecimal(rdr["NetWeight"]);
                    yarnOutward.PartyId = Convert.ToInt32(rdr["PartyId"]);
                    yarnOutward.PartyName = (rdr["PartyName"].ToString());
                    yarnOutward.CompanyId = Convert.ToInt32(rdr["YarnCompanyId"].ToString());
                    yarnOutward.CompanyName = rdr["YarnCompany"].ToString();
                    yarnOutward.Address = rdr["Address"].ToString();
                    yarnOutward.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                    yarnOutward.YarnMaterial = rdr["YarnMaterial"].ToString();
                    yarnOutward.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                    yarnOutward.YarnColor = rdr["YarnColour"].ToString();
                    yarnOutward.YarnColorCode = rdr["Code"].ToString();
                    yarnOutward.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"].ToString());
                    yarnOutward.LocationTitle = rdr["Location"].ToString();
                    yarnOutward.BoxNo = (rdr["BoxNo"].ToString());
                    yarnOutward.BarcodeNo = (rdr["BarcodeNo"].ToString());
                    yarnOutward.ChallanNo = ChallanNo;
                    yarnOutward.YarnInwardDetailID = Convert.ToInt32(rdr["YarnInwardDetailID"].ToString());
                    yarnOutward.YarnOutwardScanID = YarnOutwardScanID;
                    yarnOutward.ChallanDate = ChallanDate;
                    listPartyMaster.Add(yarnOutward);
                }
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;

            Context.Response.Write(js.Serialize(listPartyMaster));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void UpdateBoxWeight(string BoxNo, string YarnOutwardID)
        {
            string abc = YarnOutwardID;
            int YarnOutwardid = 0;
            string lastCharacter = abc.Substring(abc.Length - 6);

            if (lastCharacter != "%3d%3d")
            {
                string InvoiceId = YarnOutwardID.Replace("==", "") + "%3d%3d";
                YarnOutwardid = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
            }
            else
            {
                YarnOutwardid = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(YarnOutwardID)));
            }

            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            YarnInwardDetail yarnOutward = new YarnInwardDetail();
            CommanResponse comman = new CommanResponse();
            JavaScriptSerializer js = new JavaScriptSerializer();
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand(@"
                          IF EXISTS (SELECT 1 FROM YARNOUTWARDScanMasterDetails D
                INNER JOIN YARNOUTWARDScanMaster M ON M.YarnOutwardScanID = D.YarnOutwardScanID  WHERE D.BarcodeNo = @BarcodeNo  AND M.YarnOutwardID <> @YarnOutwardID
                            )
                            BEGIN
                                SELECT 'EXIST' AS Status
                            END
                            ELSE
                            BEGIN
                                SELECT 'NOT EXIST' AS Status,
                                       YarnInwardDetailID,
                                       BoxNo,
                                       NetWeight,
                                       BarcodeNo,
                                       GodownLocationID,
                                       YarnInwardID
                                FROM YarnInwardDetail
                                WHERE BarcodeNo = @BarcodeNo
                            END
                        ", con);

                cmd.Parameters.AddWithValue("@BarcodeNo", BoxNo);
                cmd.Parameters.AddWithValue("@YarnOutwardID", YarnOutwardid);
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.Read())
                {
                    if (rdr["Status"] != DBNull.Value && rdr["Status"].ToString() == "EXIST")
                    {
                        comman.Code = 410;
                        comman.Message = $"This Box {BoxNo} already scanned.";
                        js.MaxJsonLength = Int32.MaxValue;
                        Context.Response.Write(js.Serialize(comman));
                        return;
                    }
                    else
                    {
                        comman.Code = 201;
                        yarnOutward.YarnInwardDetailID = Convert.ToInt32(rdr["YarnInwardDetailID"]);
                        yarnOutward.BoxNo = rdr["BoxNo"].ToString();
                        yarnOutward.NetWeight = Convert.ToDecimal(rdr["NetWeight"]);
                        yarnOutward.BarcodeNo = rdr["BarcodeNo"].ToString();
                        yarnOutward.GodownLocationID = Convert.ToInt32(rdr["GodownLocationID"]);
                        yarnOutward.YarnInwardID = Convert.ToInt32(rdr["YarnInwardID"]);
                    }
                }
            }
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(yarnOutward));
        }

        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void SaveYarnoutwardScanMaster()
        {
            SqlTransaction tran = null;
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            JavaScriptSerializer js = new JavaScriptSerializer();
            CommanResponse comman = new CommanResponse();
            YarnInwardDetail yarnOutward = new YarnInwardDetail();
            try
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    con.Open();
                    tran = con.BeginTransaction();

                    string encYarnOutwardID = Context.Request.Form["YarnOutwardID"];
                    string ChallanNo = Context.Request.Form["ChallanNo"];
                    string ChallanDate = Context.Request.Form["ChallanDate"];
                    string TotalBox = Context.Request.Form["TotalBox"];
                    string TotalWeight = Context.Request.Form["TotalWeight"];
                    string PartyId = Context.Request.Form["PartyId"];
                    string scanId = Context.Request.Form["YarnOutwardScanID"];

                    int YarnOutwardScanID = string.IsNullOrEmpty(scanId) ? 0 : Convert.ToInt32(scanId);
                    int YarnOutwardID = 0;

                    if (!string.IsNullOrEmpty(encYarnOutwardID))
                    {
                        string lastCharacter = encYarnOutwardID.Substring(encYarnOutwardID.Length - 6);

                        if (lastCharacter != "%3d%3d")
                        {
                            string InvoiceId = HttpContext.Current.Request.Params["YarnOutwardID"].Replace("==", "") + "%3d%3d";
                            YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(InvoiceId)));
                        }
                        else
                        {
                            YarnOutwardID = Convert.ToInt32(Decrypt(HttpUtility.UrlDecode(HttpContext.Current.Request.Params["YarnOutwardID"])));
                        }
                    }

                    int UserAccountId = 0;

                    if (Context.Request.Cookies["UserIDs"] != null)
                    {
                        UserAccountId = Convert.ToInt32(Context.Request.Cookies["UserIDs"].Value.Split('=')[1]);
                    }

                    // INSERT OR UPDATE MASTER
                    if (YarnOutwardScanID == 0)
                    {
                        SqlCommand cmdInsert = new SqlCommand(@"
                INSERT INTO YARNOUTWARDScanMaster
                (DateAndTime,YarnOutwardID,ChallanNo,ChallanDate,TotalBox,TotalWeight,UserAccountId,FinancialYearID,CompanyId)
                VALUES
                (GETDATE(),@YarnOutwardID,@ChallanNo,@ChallanDate,@TotalBox,@TotalWeight,@UserAccountId,
                 (SELECT FinancialYearID FROM FinancialYearMaster WHERE IsDefault = 1),
                 (SELECT CompanyId FROM CompanyMaster WHERE is_default = 1))
                SELECT SCOPE_IDENTITY()", con, tran);

                        cmdInsert.Parameters.Add("@YarnOutwardID", SqlDbType.Int).Value = YarnOutwardID;
                        cmdInsert.Parameters.Add("@ChallanNo", SqlDbType.VarChar).Value = ChallanNo ?? "";
                        cmdInsert.Parameters.Add("@ChallanDate", SqlDbType.Date).Value =
                            string.IsNullOrEmpty(ChallanDate) ? (object)DBNull.Value : Convert.ToDateTime(ChallanDate);
                        cmdInsert.Parameters.Add("@TotalBox", SqlDbType.Int).Value = Convert.ToInt32(TotalBox);
                        cmdInsert.Parameters.Add("@TotalWeight", SqlDbType.Decimal).Value = Convert.ToDecimal(TotalWeight);
                        cmdInsert.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = UserAccountId;

                        YarnOutwardScanID = Convert.ToInt32(cmdInsert.ExecuteScalar());
                    }
                    else
                    {
                        SqlCommand getOldIsscandata = new SqlCommand(
                        @"SELECT YarnInwardDetailID  FROM YARNOUTWARDScanMasterDetails  WHERE YarnOutwardScanID = @YarnOutwardScanID", con, tran);
                        getOldIsscandata.Parameters.Add("@YarnOutwardScanID", SqlDbType.Int).Value = YarnOutwardScanID;
                        SqlDataReader rdr = getOldIsscandata.ExecuteReader();
                        List<int> oldIds = new List<int>();
                        while (rdr.Read())
                        {
                            oldIds.Add(Convert.ToInt32(rdr["YarnInwardDetailID"]));
                        }
                        rdr.Close();
                        foreach (var id in oldIds)
                        {
                            SqlCommand updateOld = new SqlCommand(@"
        UPDATE YarnInwardDetail  SET IsScanStutas = 0,IsScanUpdateDateTime = '1900-01-01 00:00:00.000' WHERE YarnInwardDetailID = @YarnInwardDetailID", con, tran);

                            updateOld.Parameters.Add("@YarnInwardDetailID", SqlDbType.Int).Value = id;

                            updateOld.ExecuteNonQuery();
                        }

                        SqlCommand cmdUpdate = new SqlCommand(@"
                UPDATE YARNOUTWARDScanMaster  SET ChallanNo=@ChallanNo,ChallanDate=@ChallanDate,TotalBox=@TotalBox,TotalWeight=@TotalWeight WHERE YarnOutwardScanID=@YarnOutwardScanID", con, tran);

                        cmdUpdate.Parameters.Add("@YarnOutwardScanID", SqlDbType.Int).Value = YarnOutwardScanID;
                        cmdUpdate.Parameters.Add("@ChallanNo", SqlDbType.VarChar).Value = ChallanNo ?? "";
                        cmdUpdate.Parameters.Add("@ChallanDate", SqlDbType.Date).Value =
                            string.IsNullOrEmpty(ChallanDate) ? (object)DBNull.Value : Convert.ToDateTime(ChallanDate);
                        cmdUpdate.Parameters.Add("@TotalBox", SqlDbType.Int).Value = Convert.ToInt32(TotalBox);
                        cmdUpdate.Parameters.Add("@TotalWeight", SqlDbType.Decimal).Value = Convert.ToDecimal(TotalWeight);

                        cmdUpdate.ExecuteNonQuery();

                        SqlCommand cmdDelete = new SqlCommand(
                            "DELETE FROM YARNOUTWARDScanMasterDetails WHERE YarnOutwardScanID=@YarnOutwardScanID",
                            con, tran);
                        cmdDelete.Parameters.Add("@YarnOutwardScanID", SqlDbType.Int).Value = YarnOutwardScanID;
                        cmdDelete.ExecuteNonQuery();


                    }

                    int i = 0;
                    while (Context.Request.Form["Details[" + i + "].BarcodeNo"] != null)
                    {
                        SqlCommand cmdDetail = new SqlCommand(@"
                INSERT INTO YARNOUTWARDScanMasterDetails
                (DateAndTime,YarnOutwardScanID,YarnMaterial,YarnColour,GodownLocationID,PartyID,
                 BarcodeNo,NetWeight,BoxNo,YarnInwardDetailID,UserAccountId,YarnCompany)
                VALUES
                (GETDATE(),@YarnOutwardScanID,@YarnMaterial,@YarnColour,@GodownLocationID,@PartyID,
                 @BarcodeNo,@NetWeight,@BoxNo,@YarnInwardDetailID,@UserAccountId,@YarnCompany)", con, tran);

                        cmdDetail.Parameters.Add("@YarnOutwardScanID", SqlDbType.Int).Value = YarnOutwardScanID;
                        cmdDetail.Parameters.Add("@YarnMaterial", SqlDbType.Int).Value = Convert.ToInt32(Context.Request.Form["Details[" + i + "].YarnMaterialID"]);
                        cmdDetail.Parameters.Add("@YarnColour", SqlDbType.Int).Value = Convert.ToInt32(Context.Request.Form["Details[" + i + "].YarnColorID"]);
                        cmdDetail.Parameters.Add("@GodownLocationID", SqlDbType.Int).Value = Convert.ToInt32(Context.Request.Form["Details[" + i + "].GodownLocationID"]);
                        cmdDetail.Parameters.Add("@PartyID", SqlDbType.Int).Value = Convert.ToInt32(PartyId);
                        cmdDetail.Parameters.Add("@BarcodeNo", SqlDbType.VarChar).Value = Context.Request.Form["Details[" + i + "].BarcodeNo"];
                        cmdDetail.Parameters.Add("@NetWeight", SqlDbType.Decimal).Value = Convert.ToDecimal(Context.Request.Form["Details[" + i + "].NetWeight"]);
                        cmdDetail.Parameters.Add("@BoxNo", SqlDbType.VarChar).Value = Context.Request.Form["Details[" + i + "].BoxNo"];
                        cmdDetail.Parameters.Add("@YarnInwardDetailID", SqlDbType.Int).Value = Convert.ToInt32(Context.Request.Form["Details[" + i + "].YarnInwardDetailID"]);
                        cmdDetail.Parameters.Add("@UserAccountId", SqlDbType.Int).Value = UserAccountId;
                        cmdDetail.Parameters.Add("@YarnCompany", SqlDbType.Int).Value = Convert.ToInt32(Context.Request.Form["Details[" + i + "].YarnCompany"]);
                        cmdDetail.ExecuteNonQuery();

                        SqlCommand cmdYarnInwardDetail = new SqlCommand(@"
                        UPDATE YarnInwardDetail  SET IsScanStutas = 1 , IsScanUpdateDateTime=GetDate() WHERE YarnInwardDetailID = @YarnInwardDetailID", con, tran);
                        cmdYarnInwardDetail.Parameters.Add("@YarnInwardDetailID", SqlDbType.Int).Value = Convert.ToInt32(Context.Request.Form["Details[" + i + "].YarnInwardDetailID"]);
                        cmdYarnInwardDetail.ExecuteNonQuery();
                        i++;

                    }

                    SqlCommand cmdUpdateMaster = new SqlCommand(@"
            UPDATE YARNOUTWARDMaster  SET IsScanStutas = 1 WHERE YarnOutwardID = @YarnOutwardID", con, tran);
                    cmdUpdateMaster.Parameters.Add("@YarnOutwardID", SqlDbType.Int).Value = YarnOutwardID;
                    cmdUpdateMaster.ExecuteNonQuery();
                    tran.Commit();
                    comman.Code = 201;
                    comman.Message = "Yarn Outward saved successfully.";
                }
            }
            catch (Exception ex)
            {
                if (tran != null && tran.Connection != null)
                {
                    tran.Rollback();
                }

                comman.Code = 500;
                comman.Message = ex.Message;
            }

            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(comman));
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void MoveBmpImages(string sourcePath)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            ApiResponse response = new ApiResponse();

            try
            {
                if (!Directory.Exists(sourcePath))
                    throw new Exception("Source folder not found.");

                string destPath = System.IO.Path.Combine(sourcePath, "CompressImages");

                // Create destination folder safely
                Directory.CreateDirectory(destPath);

                string[] bmpFiles = Directory.GetFiles(sourcePath, "*.bmp");

                foreach (string file in bmpFiles)
                {
                    string fileName = System.IO.Path.GetFileNameWithoutExtension(file) + ".jpg";
                    string newPath = System.IO.Path.Combine(destPath, fileName);

                    // Open file without locking
                    using (FileStream fs = new FileStream(file, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
                    {
                        GenerateThumbnailsV2(0.5, fs, newPath);
                    }
                }

                response.Code = 200;
                response.Message = " Images compressed successfully";
            }
            catch (Exception ex)
            {
                response.Code = 500;
                response.Message = ex.Message;
            }

            Context.Response.Clear();
            Context.Response.ContentType = "application/json";
            Context.Response.Write(js.Serialize(response));
            Context.Response.End();
        }

        [WebMethod]
        public void GetYarnBoxDetails(int GodownLocationID, int YarnMaterial, int YarnColour, int YarnCompany)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            List<YarnInwardDetail> list = new List<YarnInwardDetail>();

            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand(@"
                              SELECT YID.*
                        FROM YarnInwardDetail YID
                        Inner Join YarnInwardMaster YIM On YIM.YarnInwardID=YID.YarnInwardID 
                        LEFT JOIN YarnPOMaster YPM ON YPM.YarnPOID = YIM.YarnPOID
                        LEFT JOIN PartyMaster PM ON PM.PartyId = YPM.BillToPartyID
                        WHERE YID.GodownLocationID = @GodownLocationID
                        And YIM.YarnMaterialID=@YarnMaterial
                        ANd YIM.YarnColorID=@YarnColour
                        And YPM.BillToPartyID=@YarnCompany
                        AND NOT EXISTS (SELECT 1 FROM YARNOUTWARDScanMasterDetails YOSD WHERE YOSD.BarcodeNo = YID.BarcodeNo)", con);

                cmd.Parameters.AddWithValue("@GodownLocationID", GodownLocationID);
                cmd.Parameters.AddWithValue("@YarnMaterial", YarnMaterial);
                cmd.Parameters.AddWithValue("@YarnColour", YarnColour);
                cmd.Parameters.AddWithValue("@YarnCompany", YarnCompany);

                con.Open();

                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    list.Add(new YarnInwardDetail
                    {
                        YarnInwardDetailID = Convert.ToInt32(rdr["YarnInwardDetailID"].ToString()),
                        BoxNo = rdr["BoxNo"].ToString(),
                        BarcodeNo = rdr["BarcodeNo"].ToString(),
                        NetWeight = Convert.ToDecimal(rdr["NetWeight"])
                    });
                }
            }

            JavaScriptSerializer js = new JavaScriptSerializer();
            Context.Response.Write(js.Serialize(list));
        }
        [WebMethod]
        public string GetInwardTable()
        {
            var list = new List<object>();

            using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                SqlCommand cmd = new SqlCommand(@"
        SELECT *
        FROM YarnInwardMaster YIM
        INNER JOIN YarnInwardDetail YID
            ON YIM.YarnInwardID = YID.YarnInwardID
        LEFT JOIN YarnPOMaster YPM
            ON YPM.YarnPOID = YIM.YarnPOID
        LEFT JOIN PartyMaster PM
            ON PM.PartyId = YPM.BillToPartyID
        ORDER BY YIM.YarnInwardDate DESC", con);

                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                while (rdr.Read())
                {
                    list.Add(new
                    {
                        YarnInwardDate = Convert.ToDateTime(rdr["YarnInwardDate"]).ToString("yyyy-MM-dd"),
                        ChallanNo = rdr["ChallanNo"].ToString(),
                        PartyName = rdr["PartyName"].ToString(),
                        BoxNo = rdr["BoxNo"].ToString(),
                        NetWeight = rdr["NetWeight"].ToString()
                    });
                }
            }

            return new JavaScriptSerializer().Serialize(list);
        }
