                            obj.CompanyMobileNo =
                                rdr["CompanyMobileNo"]?.ToString().ToUpper() ?? "";

                            obj.CompanyAlterMobileNo =
                                rdr["CompanyAlterMobileNo"]?.ToString().ToUpper() ?? "";

                            obj.CompanyBillingAddress =
                                rdr["CompanyBillingAddress"]?.ToString().ToUpper() ?? "";

                            obj.CompanyShippingAddress =
                                rdr["CompanyShippingAddress"]?.ToString().ToUpper() ?? "";

                            obj.CompanyGSTIN =
                                rdr["CompanyGSTIN"]?.ToString().ToUpper() ?? "";

                            obj.CompanyPanNo =
                                rdr["CompanyPAN"]?.ToString().ToUpper() ?? "";

                            // =====================================
                            // SHIPPED TO
                            // =====================================

                            obj.ShippedToPartyID =
                                rdr["ShippedToPartyID"] != DBNull.Value
                                ? Convert.ToInt32(rdr["ShippedToPartyID"])
                                : 0;

                            obj.ShippedToPartyName =
                                rdr["ShippedToPartyName"]?.ToString().ToUpper() ?? "";

                            // =====================================
                            // GODOWN
                            // =====================================

                            obj.GodownID =
                                rdr["GodownID"] != DBNull.Value
                                ? Convert.ToInt32(rdr["GodownID"])
                                : 0;

                            obj.GodownTitle =
                                rdr["GodownTitle"]?.ToString().ToUpper() ?? "";

                            obj.GodownAddress =
                                rdr["GodownAddress"]?.ToString().ToUpper() ?? "";

                            obj.GodownGST =
                                rdr["GodownGST"]?.ToString().ToUpper() ?? "";

                            // =====================================
                            // TOTALS
                            // =====================================

                            obj.TotalQty =
                                rdr["TotalQty"] != DBNull.Value
                                ? Convert.ToDecimal(rdr["TotalQty"])
                                : 0;

                            obj.TotalRate =
                                rdr["TotalRate"] != DBNull.Value
                                ? Convert.ToDecimal(rdr["TotalRate"])
                                : 0;

                            obj.TotalAmount =
                                rdr["TotalAmount"] != DBNull.Value
                                ? Convert.ToDecimal(rdr["TotalAmount"])
                                : 0;

                            obj.TaxableAmount =
                                rdr["TaxableAmount"] != DBNull.Value
                                ? Convert.ToDecimal(rdr["TaxableAmount"])
                                : 0;

                            obj.GSTAmount =
                                rdr["GSTAmount"] != DBNull.Value
                                ? Convert.ToDecimal(rdr["GSTAmount"])
                                : 0;

                            obj.GrandTotal =
                                rdr["GrandTotal"] != DBNull.Value
                                ? Convert.ToDecimal(rdr["GrandTotal"])
                                : 0;

                            // =====================================
                            // EXTRA
                            // =====================================

                            obj.DeliveryTime =
                                rdr["DeliveryTime"]?.ToString().ToUpper() ?? "";

                            obj.PaymentCondition =
                                rdr["PaymentCondition"]?.ToString().ToUpper() ?? "";

                            obj.NotesRemarks =
                                rdr["NotesRemarks"]?.ToString().ToUpper() ?? "";

                            // =====================================
                            // IMPORTANT
                            // =====================================

                            obj.listYarnPODetails =
                                new List<YarnPODetails>();

                            list.Add(obj);
                        }
                    }
                }

                // =====================================================
                // DETAIL DATA
                // =====================================================

                using (SqlCommand cmd =
                    new SqlCommand("SPR_GetYarnPODetailsByIDs", con))
                {
                    cmd.CommandType = CommandType.StoredProcedure;

                    cmd.Parameters.AddWithValue("@IDs", ids);

                    using (SqlDataReader rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            int yarnPOID =
                                rdr["YarnPOID"] != DBNull.Value
                                ? Convert.ToInt32(rdr["YarnPOID"])
                                : 0;

                            YarnPOMaster master =
                                list.FirstOrDefault(
                                    x => x.YarnPOID == yarnPOID
                                );

                            if (master != null)
                            {
                                YarnPODetails detail =
                                    new YarnPODetails();

                                detail.YarnPODetailID =
                                    rdr["YarnPODetailID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnPODetailID"])
                                    : 0;

                                detail.YarnPOID =
                                    rdr["YarnPOID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnPOID"])
                                    : 0;

                                detail.YarnMaterialID =
                                    rdr["YarnMaterialID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnMaterialID"])
                                    : 0;

                                detail.YarnMaterial =
                                    rdr["YarnMaterial"]?.ToString().ToUpper() ?? "";

                                detail.YarnColorID =
                                    rdr["YarnColorID"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["YarnColorID"])
                                    : 0;

                                detail.YarnColor =
                                    rdr["YarnColor"]?.ToString().ToUpper() ?? "";

                                detail.YarnColorCode =
                                    rdr["YarnColorCode"]?.ToString().ToUpper() ?? "";

                                detail.CompanyCode =
                                    rdr["CompanyCode"]?.ToString().ToUpper() ?? "";

                                detail.Qty =
                                    rdr["Qty"] != DBNull.Value
                                    ? Convert.ToDecimal(rdr["Qty"])
                                    : 0;

                                detail.Rate =
                                    rdr["Rate"] != DBNull.Value
                                    ? Convert.ToDecimal(rdr["Rate"])
                                    : 0;

                                detail.GSTSLABId =
                                    rdr["GSTSLABId"] != DBNull.Value
                                    ? Convert.ToInt32(rdr["GSTSLABId"])
                                    : 0;

                                detail.GSTSLABName =
                                    rdr["GSTSLABName"]?.ToString().ToUpper() ?? "";

                                detail.Amount =
                                    rdr["Amount"] != DBNull.Value
                                    ? Convert.ToDecimal(rdr["Amount"])
                                    : 0;

                                master.listYarnPODetails.Add(detail);
                            }
                        }
                    }
                }
            }

            return list;
        }
        private Cell BodyCell(string text, TextAlignment align)
        {
            iText.Layout.Element.Paragraph p = new iText.Layout.Element.Paragraph(text ?? "")
                .SetFontSize(8)
                .SetMargin(0)
                .SetPadding(0)
                .SetMultipliedLeading(1);

            return new Cell()
                .Add(p)
                .SetPaddingTop(3)
                .SetPaddingBottom(3)
                .SetPaddingLeft(3)
                .SetPaddingRight(3)
                .SetTextAlignment(align)
                .SetVerticalAlignment(VerticalAlignment.MIDDLE)
                .SetBorderLeft(new SolidBorder(0.8f))
                .SetBorderRight(new SolidBorder(0.8f))
                .SetBorderBottom(iText.Layout.Borders.Border.NO_BORDER)
                .SetBorderTop(iText.Layout.Borders.Border.NO_BORDER);
        }

        public string CreatePDF(List<YarnPOMaster> data)
        {
            string dir =
                HttpContext.Current.Server.MapPath("~/GeneratedPDF/");

            if (!Directory.Exists(dir))
                Directory.CreateDirectory(dir);

            string fileName =
                $"YarnPO_{DateTime.Now:yyyyMMddHHmmss}.pdf";

            string filePath =
                System.IO.Path.Combine(dir, fileName);
              iText.Kernel.Pdf.PdfWriter writer = new iText.Kernel.Pdf.PdfWriter(filePath);

            iText.Kernel.Pdf.PdfDocument pdf =
                new iText.Kernel.Pdf.PdfDocument(writer);

            pdf.SetDefaultPageSize(iText.Kernel.Geom.PageSize.A4);

            iText.Layout.Document document =
                new iText.Layout.Document(pdf);

            document.SetMargins(10, 10, 10, 10);

       iText.Kernel.Font.PdfFont normalFont;
            iText.Kernel.Font.PdfFont boldFont;

            // =====================================================
            // FONT
            // =====================================================

            try
            {
                string f1 =
                    HttpContext.Current.Server.MapPath(
                        "~/fonts/arial.ttf"
                    );

                string f2 =
                    HttpContext.Current.Server.MapPath(
                        "~/fonts/arialbd.ttf"
                    );

                if (File.Exists(f1) && File.Exists(f2))
                {
                    normalFont = PdfFontFactory.CreateFont(f1, iText.IO.Font.PdfEncodings.IDENTITY_H);
                    boldFont = PdfFontFactory.CreateFont(f2,iText.IO.Font.PdfEncodings.IDENTITY_H);
                }
                else
                {
                    normalFont =
                        PdfFontFactory.CreateFont(
                            StandardFonts.HELVETICA
                        );

                    boldFont =
                        PdfFontFactory.CreateFont(
                            StandardFonts.HELVETICA_BOLD
                        );
                }
            }
            catch
            {
                normalFont =
                    PdfFontFactory.CreateFont(
                        StandardFonts.HELVETICA
                    );

                boldFont =
                PdfFontFactory.CreateFont(
                        StandardFonts.HELVETICA_BOLD
                    );
            }

            document.SetFont(normalFont);
            document.SetFontSize(9);

            string Safe(string s)
            {
                return s ?? "";
            }

            foreach (var item in data)
            {
                // =====================================================
                // HEADER
                // =====================================================

                iText.Layout.Element.Table header =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 1 }
                        )
                    ).UseAllAvailableWidth();

                Cell headCell = new Cell();

                headCell.Add(
                    new iText.Layout.Element.Paragraph("PURCHASE ORDER")
                    .SetFont(boldFont)
                    .SetFontSize(10)
                    .SetTextAlignment(TextAlignment.LEFT)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph(Safe(item.BillToPartyName))
                    .SetFont(boldFont)
                    .SetFontSize(15)
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph(Safe(item.BillToBillingAddress))
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph("M - " + Safe(item.BillToMobileNo))
                    .SetFont(boldFont)
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.Add(
                    new iText.Layout.Element.Paragraph("GST - " + Safe(item.BillToGSTIN))
                    .SetFont(boldFont)
                    .SetTextAlignment(TextAlignment.CENTER)
                );

                headCell.SetBorder(new SolidBorder(1));

                header.AddCell(headCell);

                document.Add(header);

                // =====================================================
                // SHIP + ORDER
                // =====================================================

                iText.Layout.Element.Table ship =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 50, 50 }
                        )
                    ).UseAllAvailableWidth();

                Cell shipLeft = new Cell();

                shipLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Shipped To Name : ").SetFont(boldFont))
                    .Add(Safe(item.GodownTitle))
                );

                shipLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Shipped To GST : ").SetFont(boldFont))
                    .Add(Safe(item.GodownGST))
                );

                shipLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Shipped To Address : ").SetFont(boldFont))
                    .Add(Safe(item.GodownAddress))
                );

                ship.AddCell(shipLeft);

                iText.Layout.Element.Table order =
                    new iText.Layout.Element.Table(1)
                    .UseAllAvailableWidth();

                order.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph()
                        .Add(new Text("ORDER DATE : ").SetFont(boldFont))
                        .Add(Safe(item.PODates))
                    )
                    .SetBorder(Border.NO_BORDER)
                );

                order.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph()
                        .Add(new Text("ORDER NUMBER : ").SetFont(boldFont))
                        .Add(item.PONo.ToString())
                    )
                    .SetBorder(Border.NO_BORDER)
                );

                ship.AddCell(new Cell().Add(order));

                document.Add(ship);

                // =====================================================
                // VENDOR
                // =====================================================

                iText.Layout.Element.Table vendor =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 50, 50 }
                        )
                    ).UseAllAvailableWidth();

                Cell vendorLeft = new Cell();

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Vendor : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierPartyName))
                );

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("GST : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierGSTIN))
                );

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Address : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierBillingAddress))
                );

                vendorLeft.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Mobile : ").SetFont(boldFont))
                    .Add(Safe(item.SupplierMobileNo))
                );

                vendor.AddCell(vendorLeft);

                Cell vendorRight = new Cell();

                vendorRight.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Company Name : ").SetFont(boldFont))
                    .Add(Safe(item.CompanyPartyName))
                );

                vendorRight.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Company GST : ").SetFont(boldFont))
                    .Add(Safe(item.CompanyGSTIN))
                );

                vendorRight.Add(
                    new iText.Layout.Element.Paragraph()
                    .Add(new Text("Company Address : ").SetFont(boldFont))
                    .Add(Safe(item.CompanyBillingAddress))
                );

                vendor.AddCell(vendorRight);

                document.Add(vendor);

                // =====================================================
                // ITEM TABLE
                // =====================================================

                float[] cols = { 8, 25, 18, 15, 10, 12, 12, 15 };

                iText.Layout.Element.Table table =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(cols)
                    )
                    .UseAllAvailableWidth();

                table.SetFixedLayout();
                table.SetFontSize(8);
                table.SetMinHeight(300);

                // =====================================================
                // HEADER
                // =====================================================

                string[] headers =
                {
            "SR",
            "Quality",
            "Colour",
            "Code",
            "Qty",
            "Rate",
            "GST %",
            "Amount"
        };

                foreach (var h in headers)
                {
                    table.AddHeaderCell(
                        new Cell()
                        .Add(
                            new iText.Layout.Element.Paragraph(h)
                            .SetFont(boldFont)
                            .SetFontSize(8)
                            .SetMargin(0)
                        )
                        .SetPadding(2)
                        .SetTextAlignment(TextAlignment.CENTER)
                        .SetVerticalAlignment(VerticalAlignment.MIDDLE)
                        .SetBackgroundColor(ColorConstants.LIGHT_GRAY)
                        .SetBorder(new SolidBorder(1))
                    );
                }

                // =====================================================
                // DATA ROWS
                // =====================================================

                decimal total = 0;
                decimal gstAmount = 0;

                int currentRows = 0;

                if (item.listYarnPODetails != null)
                {
                    int Row = 1;

                    foreach (var d in item.listYarnPODetails)
                    {
                        decimal gstPer = 0;

                        string gstText = d.GSTSLABName ?? "";

                        // KEEP ONLY NUMBERS + DOT
                        gstText = new string(
                            gstText
                            .Where(c => char.IsDigit(c) || c == '.')
                            .ToArray()
                        );

                        decimal.TryParse(gstText, out gstPer);

                        decimal rowGST =
                            (d.Amount * gstPer) / 100;

                        gstAmount += rowGST;

                        table.AddCell(
                            BodyCell(Row.ToString(), TextAlignment.CENTER)
                        );

                        table.AddCell(
                            BodyCell(Safe(d.YarnMaterial), TextAlignment.LEFT)
                        );

                        table.AddCell(
                            BodyCell(Safe(d.YarnColor), TextAlignment.LEFT)
                        );

                        table.AddCell(
                            BodyCell(Safe(d.CompanyCode), TextAlignment.LEFT)
                        );

                        table.AddCell(
                            BodyCell(
                                d.Qty.ToString("N2"),
                                TextAlignment.CENTER
                            )
                        );

                        table.AddCell(
                            BodyCell(
                                d.Rate.ToString("N2"),
                                TextAlignment.RIGHT
                            )
                        );

                        table.AddCell(
                            BodyCell(
                                gstPer.ToString("0.##") + "%",
                                TextAlignment.CENTER
                            )
                        );

                        table.AddCell(
                            BodyCell(
                                d.Amount.ToString("N2"),
                                TextAlignment.RIGHT
                            )
                        );

                        total += d.Amount;

                        Row++;
                        currentRows++;
                    }
                }

                // =====================================================
                // EMPTY ROWS
                // =====================================================

                int maxRows = 23;

                for (int i = currentRows; i < maxRows; i++)
                {
                    bool isLastRow = (i == maxRows - 1);

                    for (int c = 0; c < 8; c++)
                    {
                        table.AddCell(
                            new Cell()
                            .Add(
                                new iText.Layout.Element.Paragraph(" ")
                                .SetFontSize(8)
                                .SetMargin(0)
                            )
                            .SetHeight(16)
                            .SetPadding(0)
                            .SetBorderLeft(new SolidBorder(1))
                            .SetBorderRight(new SolidBorder(1))
                            .SetBorderTop(Border.NO_BORDER)
                            .SetBorderBottom(
                                isLastRow
                                ? new SolidBorder(1)
                                : Border.NO_BORDER
                            )
                        );
                    }
                }

                document.Add(table);

                // =====================================================
                // TOTAL
                // =====================================================

                decimal grandTotal = total + gstAmount;
                iText.Layout.Element.Table totalOuter =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 100 }
                        )
                    ).UseAllAvailableWidth();

                iText.Layout.Element.Table right =
                    new iText.Layout.Element.Table(
                        UnitValue.CreatePercentArray(
                            new float[] { 60, 40 }
                        )
                    ).UseAllAvailableWidth();

                right.AddCell(new Cell() .Add(new iText.Layout.Element.Paragraph("Total Taxable Amount :").SetFont(boldFont)).SetBorder(Border.NO_BORDER));
                right.AddCell(new Cell().Add(new iText.Layout.Element.Paragraph(total.ToString("N2")).SetTextAlignment(TextAlignment.RIGHT)).SetBorder(Border.NO_BORDER));

                right.AddCell(new Cell()    .Add(
                        new iText.Layout.Element.Paragraph("GST Amount :")
                        .SetFont(boldFont)
                    )
                    .SetBorder(Border.NO_BORDER)
                );

                right.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph(gstAmount.ToString("N2"))
                        .SetTextAlignment(TextAlignment.RIGHT)
                    )
                    .SetBorder(Border.NO_BORDER)
                );

                right.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph("Grand Total :")
                        .SetFont(boldFont)
                    )
                    .SetBorder(Border.NO_BORDER)
                );

                right.AddCell(
                    new Cell()
                    .Add(
                        new iText.Layout.Element.Paragraph(grandTotal.ToString("N2"))
                        .SetFont(boldFont)
                        .SetTextAlignment(TextAlignment.RIGHT)
                    )
                    .SetBorder(Border.NO_BORDER)
                );

                totalOuter.AddCell(
                    new Cell()
                    .Add(right)
                    .SetBorder(new SolidBorder(1))
                );

                document.Add(totalOuter);

                // =====================================================
                // PAGE BREAK
                // =====================================================

                if (!item.Equals(data.Last()))
                {
                    document.Add(
                        new AreaBreak(AreaBreakType.NEXT_PAGE)
                    );
                }
            }

            document.Close();

            return "/GeneratedPDF/" + fileName;
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]
        public void YarnPendingPOReport()
        {
            JavaScriptSerializer js;
            List<YarnPOMaster> listUser = new List<YarnPOMaster>();
            YarnPOMasterResponse response = new YarnPOMasterResponse();

            var request = HttpContext.Current.Request;
            YarnPOMaster ilist = new YarnPOMaster();
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;
            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand();
                cmd.Connection = con;
                cmd.CommandType = System.Data.CommandType.Text;
                //cmd.CommandText = "select PM.* from PartyMaster PM LEFT JOIN CompanyMaster CM ON PM.CompanyId = CM.CompanyId where CM.is_default = '1' and PM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " and PM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1) order by PM.PartyId desc OFFSET " + ilist.startFrom.ToString() + " ROWS FETCH NEXT 10 ROWS ONLY";
                cmd.CommandText = "SELECT YPM.PONo, YPM.PODate, " +
                    " YPM.SupplierPartyName, YPM.SupplierMobileNo, YPM.SupplierAlterMobileNo, " +
                    " YPM.BillToPartyName, YPM.BillToMobileNo, YPM.BillToAlterMobileNo, YPM.BillToEmail, " +
                    " YPM.CompanyPartyName, YPM.CompanyMobileNo, YPM.CompanyAlterMobileNo, YPM.CompanyEmail, " +
                    " YPM.ShippedToPartyName, YPM.ShippedToMobileNo, YPM.ShippedToAlterMobileNo, YPM.ShippedToEmail," +
                    " YPM.GodownTitle, YPM.GodownAddress, YMM.YarnMaterial, YCM.YarnColor, temp.* " +
                    " FROM " +
                    " ( " +
                    " 	SELECT ypd.*, ISNULL(yim.Received,0) as Received, " +
                    " 	ypd.Qty - ISNULL(yim.Received,0) as PendingQty" +
                    "  	FROM YarnPODetails ypd " +
                    " 	LEFT JOIN " +
                    " 	(" +
                    " 		SELECT SUM(TotalWeight) as Received, YarnMaterialID , YarnPODetailIDCompanyCode, IsComplete" +
                    " 		FROM YarnInwardMaster " +
                    " 		where CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " 		and FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1) " +
                    " 		and UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + "" +
                    " 		GROUP BY YarnMaterialID, YarnPODetailIDCompanyCode, IsComplete" +
                    " 	) as yim ON ypd.YarnPODetailID = yim.YarnPODetailIDCompanyCode" +
                    " ) as temp" +
                    " LEFT JOIN " +
                    " (" +
                    " 	select YPM.*," +
                    " 	SPM.PartyName as SupplierPartyName, SPM.MobileNo as SupplierMobileNo, SPM.AlterMobileNo as SupplierAlterMobileNo, " +
                    " 	BPM.PartyName as BillToPartyName, BPM.MobileNo as BillToMobileNo, BPM.AlterMobileNo as BillToAlterMobileNo, BPM.Email as BillToEmail," +
                    " 	CPM.PartyName as CompanyPartyName, CPM.MobileNo as CompanyMobileNo, CPM.AlterMobileNo as CompanyAlterMobileNo, CPM.Email as CompanyEmail," +
                    " 	SPPM.PartyName as ShippedToPartyName, SPPM.MobileNo as ShippedToMobileNo, SPPM.AlterMobileNo as ShippedToAlterMobileNo, SPPM.Email as ShippedToEmail," +
                    " 	GM.GodownTitle, GM.GodownAddress " +
                    " 	from YarnPOMaster YPM" +
                    " 	LEFT JOIN PartyMaster SPM ON YPM.SupplierPartyID = SPM.PartyId " +
                    " 	LEFT JOIN PartyMaster BPM ON YPM.BillToPartyID = BPM.PartyId " +
                    " 	LEFT JOIN PartyMaster CPM ON YPM.CompanyPartyID = CPM.PartyId" +
                    " 	LEFT JOIN PartyMaster SPPM ON YPM.ShippedToPartyID = SPPM.PartyId" +
                    " 	LEFT JOIN GodownMaster GM ON GM.GodownID = YPM.GodownID" +
                    " 	where YPM.CompanyId = (select CompanyId from CompanyMaster where is_default = 1)" +
                    " 		and YPM.FinancialYearID = (select FinancialYearID from FinancialYearMaster where IsDefault = 1)" +
                    " 		and YPM.UserAccountId = " + Context.Request.Cookies["UserIDs"].Value.Split('=')[1] + " " +
                    " )as YPM ON YPM.YarnPOID = temp.YarnPOID" +
                    " LEFT JOIN YarnMaterialMaster YMM ON YMM.YarnMaterialID = temp.YarnMaterialID" +
                    " LEFT JOIN YarnColorMaster YCM ON YCM.YarnColorID = temp.YarnColorID";
                con.Open();
                SqlDataReader rdr = cmd.ExecuteReader();

                if (rdr.HasRows)
                {
                    while (rdr.Read())
                    {
                        YarnPOMaster condition = new YarnPOMaster();
                        condition.YarnPOID = Convert.ToInt32(rdr["YarnPOID"].ToString());
                        condition.YarnPODetailID = Convert.ToInt32(rdr["YarnPODetailID"].ToString());
                        condition.PODate = Convert.ToDateTime(rdr["PODate"].ToString());
                        condition.PODates = Convert.ToDateTime(rdr["PODate"].ToString()).ToString("dd-MM-yyyy");
                        condition.PONo = Convert.ToInt32(rdr["PONo"].ToString());
                        condition.SupplierPartyName = rdr["SupplierPartyName"].ToString().ToUpper();
                        condition.SupplierMobileNo = rdr["SupplierMobileNo"].ToString().ToUpper();
                        condition.SupplierAlterMobileNo = rdr["SupplierAlterMobileNo"].ToString().ToUpper();
                        condition.BillToPartyName = rdr["BillToPartyName"].ToString().ToUpper();
                        condition.BillToMobileNo = rdr["BillToMobileNo"].ToString().ToUpper();
                        condition.BillToAlterMobileNo = rdr["BillToAlterMobileNo"].ToString().ToUpper();
                        condition.CompanyPartyName = rdr["CompanyPartyName"].ToString().ToUpper();
                        condition.CompanyMobileNo = rdr["CompanyMobileNo"].ToString().ToUpper();
                        condition.CompanyAlterMobileNo = rdr["CompanyAlterMobileNo"].ToString().ToUpper();
                        condition.ShippedToPartyName = rdr["ShippedToPartyName"].ToString().ToUpper();
                        condition.ShippedToMobileNo = rdr["ShippedToMobileNo"].ToString().ToUpper();
                        condition.ShippedToAlterMobileNo = rdr["ShippedToAlterMobileNo"].ToString().ToUpper();
                        condition.GodownTitle = rdr["GodownTitle"].ToString().ToUpper();
                        condition.GodownAddress = rdr["GodownAddress"].ToString().ToUpper();
                        condition.YarnMaterialID = Convert.ToInt32(rdr["YarnMaterialID"].ToString());
                        condition.YarnMaterial = rdr["YarnMaterial"].ToString().ToUpper();
                        condition.YarnColorID = Convert.ToInt32(rdr["YarnColorID"].ToString());
                        condition.YarnColor = rdr["YarnColor"].ToString().ToUpper();
                        condition.CompanyCode = rdr["CompanyCode"].ToString().ToUpper();
                        condition.Qty = Convert.ToDecimal(rdr["Qty"].ToString().ToUpper());
                        condition.PendingQty = Convert.ToDecimal(rdr["PendingQty"].ToString().ToUpper());
                        condition.IsComplete = Convert.ToBoolean(rdr["IsClose"]);
                        listUser.Add(condition);
                    }
                }
                rdr.Close();
                cmd.Dispose();
                con.Close();
            }


            System.Web.HttpCookie nameCookie = new System.Web.HttpCookie("DesignColorMatchingFormIDs");
            nameCookie.Expires = DateTime.Now.AddDays(-1);
            Context.Response.Cookies.Add(nameCookie);

            response.Code = 200;
            response.Message = "Success";
            response.listYarnPOMaster = listUser;

            js = new JavaScriptSerializer();
            js.MaxJsonLength = Int32.MaxValue;
            Context.Response.Write(js.Serialize(response));
            return;
        }
        [WebMethod]
        public string EmptyLocationReport()
        {
            List<object> list = new List<object>();
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                string query = @"SELECT GL.GodownLocationID,GL.LocationTitle,GL.GodownID, 
                                GM.GodownTitle,GM.GodownAddress
                         FROM GodownLocationMaster GL
                         INNER JOIN GodownMaster GM 
                            ON GL.GodownID = GM.GodownID
                         WHERE NOT EXISTS (
                            SELECT 1 
                            FROM YarnInwardDetail YI 
                            WHERE YI.GodownLocationID = GL.GodownLocationID
                         )";

                SqlCommand cmd = new SqlCommand(query, con);
                con.Open();
                SqlDataReader dr = cmd.ExecuteReader();

                while (dr.Read())
                {
                    list.Add(new
                    {
                        GodownLocationID = dr["GodownLocationID"],
                        LocationTitle = dr["LocationTitle"].ToString(),
                        GodownID = dr["GodownID"],
                        GodownTitle = dr["GodownTitle"].ToString(),
                        GodownAddress = dr["GodownAddress"].ToString()
                    });
                }
            }

            var result = new
            {
                result = "1",
                message = "Success",
                data = list
            };

            return new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(result);
        }
        [WebMethod]
        public string YarnInterChangeReport()
        {
            try
            {
                string query = @"WITH InterchangeHistory AS (SELECT T.YarnInterchangeID,T.DateAndTime,T.YarnInwardDetailID,T.YarnMaterialID,T.YarnColorID,
        T.YarnPOID,T.GodownID,T.GodownLocationID,T.UserAccountId,YID.BoxNo,YID.NetWeight,YID.YarnInwardID,        
        LAG(T.GodownLocationID) OVER ( PARTITION BY T.YarnInwardDetailID,YID.BoxNo,T.YarnMaterialID,T.YarnColorID  ORDER BY T.YarnInterchangeID
        ) AS OldLocationID FROM YarnInterchangeMaster T
    INNER JOIN YarnInwardDetail YID ON T.YarnInwardDetailID = YID.YarnInwardDetailID)
SELECT T.YarnInterchangeID,T.DateAndTime, UA.UserAccountName AS [User],T.BoxNo AS Box,YMM.YarnMaterial AS Material,YCM.YarnColor AS Color, PM.PartyName AS Party,
    YPM.PONo AS PO,GM.GodownTitle AS Godown,GLM_OLD.LocationTitle AS [From],GLM_NEW.LocationTitle AS [To],T.NetWeight AS Wt,'YES' AS Move
FROM InterchangeHistory T
LEFT JOIN YarnMaterialMaster YMM ON T.YarnMaterialID = YMM.YarnMaterialID
LEFT JOIN YarnColorMaster YCM ON T.YarnColorID = YCM.YarnColorID
LEFT JOIN YarnInwardMaster YIM ON T.YarnInwardID = YIM.YarnInwardID
LEFT JOIN YarnPOMaster YPM ON T.YarnPOID = YPM.YarnPOID
LEFT JOIN PartyMaster PM ON YPM.BillToPartyID = PM.PartyId
LEFT JOIN GodownMaster GM ON T.GodownID = GM.GodownID
LEFT JOIN GodownLocationMaster GLM_NEW ON T.GodownLocationID = GLM_NEW.GodownLocationID
LEFT JOIN GodownLocationMaster GLM_OLD ON T.OldLocationID = GLM_OLD.GodownLocationID
LEFT JOIN UserAccountMaster UA ON T.UserAccountId = UA.UserAccountId
WHERE T.OldLocationID IS NOT NULL
ORDER BY T.BoxNo,T.DateAndTime,T.YarnInterchangeID;";

                DataTable dt = new DataTable();

                string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

                using (SqlConnection con = new SqlConnection(cs))
                {
                    using (SqlCommand cmd = new SqlCommand(query, con))
                    {
                        cmd.CommandTimeout = 0;

                        using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                        {
                            da.Fill(dt);
                        }
                    }
                }

                return JsonConvert.SerializeObject(dt);
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(new
                {
                    Status = "Error",
                    Message = ex.Message
                });
            }
        }
        [WebMethod]
        public string GetMovementHistory(int yarnDetailId)
        {
            string query = @"
    SELECT 
        YT.DateAndTime,
        LAG(GLM.LocationTitle) OVER (ORDER BY YT.YarnInterchangeID) AS FromLocation,
        GLM.LocationTitle AS ToLocation,
        YT.UserAccountId
    FROM YarnInterchangeMaster YT
    LEFT JOIN GodownLocationMaster GLM 
        ON YT.GodownLocationID = GLM.GodownLocationID
    WHERE YT.YarnInwardDetailID = @Id
    ORDER BY YT.YarnInterchangeID
    ";

            DataTable dt = new DataTable();

            using (SqlConnection con = new SqlConnection(ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString))
            {
                using (SqlCommand cmd = new SqlCommand(query, con))
                {
                    cmd.Parameters.AddWithValue("@Id", yarnDetailId);

                    using (SqlDataAdapter da = new SqlDataAdapter(cmd))
                    {
                        da.Fill(dt);
                    }
                }
            }

            return JsonConvert.SerializeObject(dt);
        }
        [WebMethod]
        [ScriptMethod(ResponseFormat = ResponseFormat.Json)]

        public object GetColorMatchingReport(int pageNumber, int pageSize, string validationStatus = "", string searchText = "")
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            try
            {
                using (SqlConnection con = new SqlConnection(cs))
                {
                    int offset = (pageNumber - 1) * pageSize;

                    // =========================
                    // 🔹 MAIN QUERY
                    // =========================
                    string query = @"
WITH FormStatus AS (
    SELECT 
        DCMFM.DesignColorMatchingFormID,
        DCMFM.DesignEntryFormID,
        CASE 
            WHEN COUNT(d.DesignColorMatchingDetailsID) > 0 THEN 'Validated'
            ELSE 'Not Validated'
        END AS ValidationStatus
    FROM DesignColorMatchingFormMaster DCMFM
    LEFT JOIN DesignColorMatchingDetails d 
        ON d.DesignColorMatchingFormID = DCMFM.DesignColorMatchingFormID
        AND ISNULL(d.ColorMatchingPhoto,'') <> ''
    GROUP BY DCMFM.DesignColorMatchingFormID, DCMFM.DesignEntryFormID
),

Filtered AS (
    SELECT FS.*
    FROM FormStatus FS
    LEFT JOIN DesignEntryFormMaster DEFM 
        ON DEFM.DesignEntryFormID = FS.DesignEntryFormID

    WHERE 
        (@validationStatus = '' OR FS.ValidationStatus = @validationStatus)
        AND (
            @searchText = '' OR
            LOWER(ISNULL(DEFM.DesignNo,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignNo,'') + ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%'
        )
),

Paginated AS (
    SELECT *
    FROM Filtered
    ORDER BY DesignColorMatchingFormID DESC
    OFFSET @offset ROWS FETCH NEXT @pageSize ROWS ONLY
)

SELECT DCMFM.*,DEFM.DesignerCode,DEFM.DesignNo,DEFM.TotalCard,DEFM.PickOnLoom,WQ.WarpQuality,DCM.DesignCategory,DCMD.MatchingNo,
    DCMD.MatchingID,DCMD.Warp1,DCMD.Warp2,DCMD.Warp3,DCMD.Warp4,DCMD.Warp5,DCMD.Feeder1,DCMD.Feeder2,DCMD.Feeder3,DCMD.Feeder4,DCMD.Feeder5,
        P.ValidationStatus

FROM Paginated P
JOIN DesignColorMatchingFormMaster DCMFM 
    ON DCMFM.DesignColorMatchingFormID = P.DesignColorMatchingFormID

LEFT JOIN DesignColorMatchingDetails DCMD
    ON DCMFM.DesignColorMatchingFormID = DCMD.DesignColorMatchingFormID

LEFT JOIN DesignEntryFormMaster DEFM 
    ON DEFM.DesignEntryFormID = DCMFM.DesignEntryFormID

LEFT JOIN WarpQualityMaster WQ 
    ON WQ.WarpQualityID = DEFM.WarpQualityID

LEFT JOIN DesignCategoryMaster DCM 
    ON DCM.DesignCategoryID = DEFM.DesignCategoryID
";

                    SqlCommand cmd = new SqlCommand(query, con);
                    cmd.Parameters.Add("@offset", SqlDbType.Int).Value = offset;
                    cmd.Parameters.Add("@pageSize", SqlDbType.Int).Value = pageSize;
                    cmd.Parameters.Add("@validationStatus", SqlDbType.VarChar).Value = validationStatus ?? "";
                    cmd.Parameters.Add("@searchText", SqlDbType.VarChar).Value = searchText ?? "";

                    SqlDataAdapter da = new SqlDataAdapter(cmd);
                    DataTable dt = new DataTable();
                    da.Fill(dt);

                    var list = new List<Dictionary<string, object>>();

                    foreach (DataRow row in dt.Rows)
                    {
                        var dict = new Dictionary<string, object>();
                        foreach (DataColumn col in dt.Columns)
                        {
                            dict[col.ColumnName] = row[col];
                        }
                        list.Add(dict);
                    }

                    // =========================
                    // 🔹 COUNT QUERY
                    // =========================
                    string countQuery = @"
WITH FormStatus AS (
    SELECT 
        DCMFM.DesignColorMatchingFormID,
        DCMFM.DesignEntryFormID,
        CASE 
            WHEN COUNT(d.DesignColorMatchingDetailsID) > 0 THEN 'Validated'
            ELSE 'Not Validated'
        END AS ValidationStatus
    FROM DesignColorMatchingFormMaster DCMFM
    LEFT JOIN DesignColorMatchingDetails d 
        ON d.DesignColorMatchingFormID = DCMFM.DesignColorMatchingFormID
        AND ISNULL(d.ColorMatchingPhoto,'') <> ''
    GROUP BY DCMFM.DesignColorMatchingFormID, DCMFM.DesignEntryFormID
),

Filtered AS (
    SELECT FS.*
    FROM FormStatus FS
    LEFT JOIN DesignEntryFormMaster DEFM 
        ON DEFM.DesignEntryFormID = FS.DesignEntryFormID

    WHERE 
        (@validationStatus = '' OR FS.ValidationStatus = @validationStatus)
        AND (
            @searchText = '' OR
            LOWER(ISNULL(DEFM.DesignNo,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%' OR
            LOWER(ISNULL(DEFM.DesignNo,'') + ISNULL(DEFM.DesignerCode,'')) LIKE '%' + LOWER(@searchText) + '%'
        )
)

SELECT 
    COUNT(*) AS TotalRecords,
    SUM(CASE WHEN ValidationStatus = 'Validated' THEN 1 ELSE 0 END) AS ValidatedCount,
    SUM(CASE WHEN ValidationStatus = 'Not Validated' THEN 1 ELSE 0 END) AS NotValidatedCount
FROM Filtered
";

                    SqlCommand countCmd = new SqlCommand(countQuery, con);
                    countCmd.Parameters.Add("@validationStatus", SqlDbType.VarChar).Value = validationStatus ?? "";
                    countCmd.Parameters.Add("@searchText", SqlDbType.VarChar).Value = searchText ?? "";

                    con.Open();
                    SqlDataReader reader = countCmd.ExecuteReader();

                    int total = 0, validated = 0, notValidated = 0;

                    if (reader.Read())
                    {
                        total = Convert.ToInt32(reader["TotalRecords"]);
                        validated = Convert.ToInt32(reader["ValidatedCount"]);
                        notValidated = Convert.ToInt32(reader["NotValidatedCount"]);
                    }

                    con.Close();

                    return new
                    {
                        Success = true,
                        Message = "Data loaded successfully",
                        Data = list,
                        TotalRecords = total,
                        ValidatedCount = validated,
                        NotValidatedCount = notValidated
                    };
                }
            }
            catch (Exception ex)
            {
                return new
                {
                    Success = false,
                    Message = ex.Message
                };
            }
        }
        [WebMethod]
        public void ClosePO(int id)
        {
            string UserAccountId = Context.Request.Cookies["UserIDs"].Value.Split('=')[1];
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                con.Open();

                SqlTransaction trans = con.BeginTransaction();

                try
                {
                    SqlCommand cmd = new SqlCommand();
                    cmd.Connection = con;
                    cmd.Transaction = trans;
                    //// ✅ 1. Update Inward Master
                    //cmd.CommandText = @"UPDATE YarnInwardMaster SET IsComplete = 1 WHERE YarnPODetailIDCompanyCode = @Code";
                    //cmd.Parameters.Clear();
                    //cmd.Parameters.AddWithValue("@Code", id);
                    //cmd.ExecuteNonQuery();

                    // ✅ 2. Update PO Details (Close)
                    cmd.CommandText = @"UPDATE YarnPODetails SET IsClose = 1,IsCloseDateTime = GETDATE(),IsCloseUserID = @UserID  WHERE YarnPODetailID = @Code";
                    cmd.Parameters.Clear();
                    cmd.Parameters.AddWithValue("@Code", id);
                    cmd.Parameters.AddWithValue("@UserID", UserAccountId);
                    cmd.ExecuteNonQuery();
                    trans.Commit();
                }
                catch (Exception ex)
                {
                    // ❌ Rollback if error
                    trans.Rollback();
                    throw;
                }
            }
        }
        [WebMethod]
        public void ReopenPO(int id)
        {
            string cs = ConfigurationManager.ConnectionStrings["sqlconnstr"].ConnectionString;

            using (SqlConnection con = new SqlConnection(cs))
            {
                SqlCommand cmd = new SqlCommand(
                    @"UPDATE YarnPODetails SET IsClose = 0,IsCloseDateTime = NULL,IsCloseUserID = NULL WHERE YarnPODetailID = @id",
                    con);

                cmd.Parameters.AddWithValue("@id", id);

                con.Open();
                cmd.ExecuteNonQuery();
                con.Close();
            }
        }

        [WebMethod]
        public object ExportPDF(List<int> yarnPOIds)
        {
            try
            {
                string folderPath = HttpContext.Current.Server.MapPath("~/GeneratedPDF/");

                if (!Directory.Exists(folderPath))
                {
                    Directory.CreateDirectory(folderPath);
                }

                // Final Merge PDF Name
                string fileName = "PurchaseOrder_" +
                                  DateTime.Now.ToString("yyyyMMddHHmmss") + ".pdf";

                string fullPath = System.IO.Path.Combine(folderPath, fileName);

                // Store all PDF bytes
                List<byte[]> pdfBytesList = new List<byte[]>();

                foreach (int poId in yarnPOIds)
                {
                    var data = GetYarnPODataForPDF_DB(poId);

                    if (data == null || data.Count == 0)
                    {
                        continue;
                    }

                    Microsoft.Reporting.WebForms.LocalReport report =
                        new Microsoft.Reporting.WebForms.LocalReport();

                    report.ReportPath = HttpContext.Current.Server.MapPath("~/Reports/PurchaseOrder.rdlc");

                    report.EnableExternalImages = true;

                    report.DataSources.Clear();

                    // Master Dataset
                    Microsoft.Reporting.WebForms.ReportDataSource dsMaster =
                        new Microsoft.Reporting.WebForms.ReportDataSource("Master", data);

                    report.DataSources.Add(dsMaster);

                    // Detail Dataset
                    var detailData = data.SelectMany(x => x.listYarnPODetails).ToList();

                    Microsoft.Reporting.WebForms.ReportDataSource dsDetail =
                        new Microsoft.Reporting.WebForms.ReportDataSource("OrderDetails", detailData);

                    report.DataSources.Add(dsDetail);

                    report.Refresh();

                    string mimeType;
                    string encoding;
                    string extension;
                    string[] streamids;
                    Microsoft.Reporting.WebForms.Warning[] warnings;

                    byte[] bytes = report.Render(
                        "PDF",
                        null,
                        out mimeType,
                        out encoding,
                        out extension,
                        out streamids,
                        out warnings
                    );

                    // Add PDF bytes to list
                    pdfBytesList.Add(bytes);
                }

                // =========================================
                // MERGE PDF
                // =========================================

                using (FileStream stream = new FileStream(fullPath, FileMode.Create))
                {
                    using (Document document = new Document())
                    {
                        PdfCopy pdfCopy = new PdfCopy(document, stream);

                        document.Open();

                        foreach (byte[] pdfBytes in pdfBytesList)
                        {
                            PdfReader reader = new PdfReader(pdfBytes);

                            for (int i = 1; i <= reader.NumberOfPages; i++)
                            {
                                PdfImportedPage page = pdfCopy.GetImportedPage(reader, i);

                                pdfCopy.AddPage(page);
                            }

                            reader.Close();
                        }

                        document.Close();
                    }
                }

                string filePath =
                    HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority)
                    + "/GeneratedPDF/" + fileName;

                return new
                {
                    Status = true,
                    Message = "PDF Generated Successfully",
                    FilePath = filePath
                };
            }
            catch (Exception ex)
            {
                return new
                {
                    Status = false,
                    Message = ex.ToString(),
                    FilePath = ""
                };
            }
        }

        [WebMethod]
        public object ExportPDF1(List<int> yarnPOIds)
        {
            try
            {
                string connStr =
                    ConfigurationManager
                    .ConnectionStrings["sqlconnstr"]
                    .ConnectionString;

                // STORE ALL PDF BYTES
                List<byte[]> pdfBytesList =  new List<byte[]>();

                using (SqlConnection con = new SqlConnection(connStr))
                {
                    con.Open();
                    // LOOP ALL PO IDS
                    foreach (int poId in yarnPOIds)
                    {
                        DataSet ds = new DataSet();

                        // =========================================
                        // MASTER QUERY
                        // =========================================

                        string masterQuery = @"

                    SELECT
                        YPM.*,

                        SPM.PartyName AS SupplierPartyName,
                        CPM.PartyName AS BillToPartyName,
                        BPM.PartyName AS CompanyPartyName,
                        SPPM.PartyName AS ShippedToPartyName,

                        GM.GodownTitle,
                        GM.GodownAddress,

                        ISNULL(X.TaxableAmount,0) AS TaxableAmount,
                        ISNULL(X.GSTAmount,0) AS GSTAmount,
                        ISNULL(X.GrandTotal,0) AS GrandTotal

                    FROM YarnPOMaster YPM

                    LEFT JOIN PartyMaster SPM
                        ON YPM.SupplierPartyID = SPM.PartyId

                    LEFT JOIN PartyMaster BPM
                        ON YPM.BillToPartyID = BPM.PartyId

                    LEFT JOIN PartyMaster CPM
                        ON YPM.CompanyPartyID = CPM.PartyId

                    LEFT JOIN PartyMaster SPPM
                        ON YPM.ShippedToPartyID = SPPM.PartyId

                    LEFT JOIN GodownMaster GM
                        ON GM.GodownID = YPM.GodownID

                    OUTER APPLY
                    (
                        SELECT

                            SUM(ISNULL(YPD.Amount,0))
                            AS TaxableAmount,

                            SUM
                            (
                                ISNULL
                                (
                                    (YPD.Amount * GSM.IGST) / 100,
                                    0
                                )
                            )
                            AS GSTAmount,

                            SUM(ISNULL(YPD.Amount,0))
                            +
                            SUM
                            (
                                ISNULL
                                (
                                    (YPD.Amount * GSM.IGST) / 100,
                                    0
                                )
                            )
                            AS GrandTotal

                        FROM YarnPODetails YPD

                        LEFT JOIN GSTSLABMaster GSM
                            ON YPD.GSTSLABId =
                               GSM.GSTSLABId

                        WHERE YPD.YarnPOID =
                              YPM.YarnPOID

                    ) X

                    WHERE YPM.YarnPOID = @YarnPOID";

                        using (SqlCommand cmd = new SqlCommand(masterQuery, con))
                        {
                            cmd.CommandType = CommandType.Text;
                            cmd.Parameters.AddWithValue("@YarnPOID",poId);
                            SqlDataAdapter da =new SqlDataAdapter(cmd);
                            da.Fill(ds, "DSMaster");
                        }

                        // =========================================
                        // DETAIL QUERY
                        // =========================================

                        string detailQuery = @"

                    SELECT

                        YPD.YarnPODetailID,
                        YPD.YarnPOID,
                        YPD.YarnMaterialID,

                        YMM.YarnMaterial,

                        YPD.YarnColorID,

                        YCM.YarnColor,
                        YCM.YarnColorCode,

                        YPD.CompanyCode,
                        YPD.Qty,
                        YPD.Rate,

                        YPD.GSTSLABId,

                        GSM.GSTSLABName,

                        YPD.Amount

                    FROM YarnPODetails YPD

                    LEFT JOIN YarnMaterialMaster YMM
                        ON YMM.YarnMaterialID =
                           YPD.YarnMaterialID

                    LEFT JOIN YarnColorMaster YCM
                        ON YCM.YarnColorID =
                           YPD.YarnColorID

                    LEFT JOIN GSTSLABMaster GSM
                        ON YPD.GSTSLABId =
                           GSM.GSTSLABId

                    WHERE YPD.YarnPOID =
                          @YarnPOID";

                        using (SqlCommand cmd =
                            new SqlCommand(detailQuery, con))
                        {
                            cmd.CommandType =
                                CommandType.Text;

                            cmd.Parameters.AddWithValue(
                                "@YarnPOID",
                                poId);

                            SqlDataAdapter da =
                                new SqlDataAdapter(cmd);

                            da.Fill(ds, "DSDetail");
                        }

                        // =========================================
                        // CHECK DATA
                        // =========================================

                        if (ds.Tables["DSMaster"]
                            .Rows.Count == 0)
                        {
                            continue;
                        }

                        // =========================================
                        // RDLC REPORT
                        // =========================================

                        LocalReport report = new LocalReport();
                        report.ReportPath = HttpContext.Current.Server.MapPath("~/Reports/PurchaseOrder1.rdlc");
                        report.DataSources.Clear();
                        // MASTER DATASET
                        report.DataSources.Add(new ReportDataSource("DSMaster",ds.Tables["DSMaster"]));
                        // DETAIL DATASET
                        report.DataSources.Add(new ReportDataSource("DSDetail",ds.Tables["DSDetail"]));
                        // =========================================
                        // PDF SETTINGS
                        // =========================================
                        string deviceInfo =
                            "<DeviceInfo>" +
                            "<OutputFormat>PDF</OutputFormat>" +
                            "<PageWidth>8.27in</PageWidth>" +
                            "<PageHeight>11.69in</PageHeight>" +
                            "<MarginTop>0.25in</MarginTop>" +
                            "<MarginLeft>0.25in</MarginLeft>" +
                            "<MarginRight>0.25in</MarginRight>" +
                            "<MarginBottom>0.25in</MarginBottom>" +
                            "</DeviceInfo>";
                        Warning[] warnings;
                        string[] streams;
                        string mimeType;
                        string encoding;
                        string extension;
                        // =========================================
                        // RENDER PDF
                        // =========================================

                        byte[] pdfBytes =
                            report.Render(
                                "PDF",
                                deviceInfo,
                                out mimeType,
                                out encoding,
                                out extension,
                                out streams,
                                out warnings);

                        // STORE PDF
                        pdfBytesList.Add(pdfBytes);
                    }
                }
                string folderPath = HttpContext.Current.Server.MapPath("~/PDFReports/");
                if (!Directory.Exists(folderPath))
                {
                    Directory.CreateDirectory(folderPath);
                }
                string fileName = "PurchaseOrder_" + DateTime.Now.ToString("ddMMyyyyHHmmss") +".pdf";
                string fullPath = System.IO.Path.Combine(folderPath,fileName);
                using (FileStream stream = new FileStream(fullPath,FileMode.Create))
                {
                    using ( Document document = new Document())
                    {
                        PdfCopy pdfCopy = new PdfCopy(document,stream);
                        document.Open();
                        foreach (byte[] pdfBytes in pdfBytesList)
                        {
                            PdfReader reader = new PdfReader(pdfBytes);
                            for (int i = 1; i <= reader.NumberOfPages;i++)
                            {
                                PdfImportedPage page = pdfCopy.GetImportedPage(reader,i);
                                pdfCopy.AddPage(page);
                            }
                            reader.Close();
                        }
                        document.Close();
                    }
                }                
                string filePath = HttpContext.Current.Request.Url.GetLeftPart(UriPartial.Authority) + "/PDFReports/"+ fileName;
                return JsonConvert.SerializeObject( new
                {
                        Status = true,
                        Message =
                            "PDF Generated Successfully",
                        FilePath = filePath
                });
            }
            catch (Exception ex)
            {
                return JsonConvert.SerializeObject(
                    new
                    {
                        Status = false,
                        Message = ex.Message
                    });
            }
        }
    }
}
